429:/* Hardened tier (P7): the kb connects as a non-owner runtime role that CANNOT apply
430: * owner-only DDL. The schema is applied by a separate migrate/owner step; here we
431: * VERIFY (read-only) that the migrated schema is present, current, and dim-
432: * compatible, and fail closed otherwise — never attempting the apply. Every query
433: * is a plain SELECT / catalog lookup a non-owner runtime role may run. Called only
434: * when db2_hardening_enabled(); the dev/owner path still auto-applies as before. */
435:static int db2_verify_pre_provisioned(void *conn, int expected_dim, char *err, size_t errlen)
436:{
437:   /* 1. Embedding dim: recorded (proves the migrate ran) and equal to what this kb
438:    *    will size its halfvec columns / readers to. */
439:   int recorded_dim = 0;
440:   db2_dim_read_t rd = db2_embedding_dim_read(conn, &recorded_dim);
441:   if (rd == DB2_DIM_ERROR)
442:   {
443:      snprintf(err, errlen, "hardened tier: could not read the recorded embedding dim");
444:      return -1;
445:   }
446:   if (rd != DB2_DIM_FOUND)
447:   {
448:      snprintf(err, errlen,
449:               "hardened tier: schema is not migrated (no recorded embedding dim). A "
450:               "runtime-role kb cannot apply the schema — run the owner/migrate step first.");
451:      return -1;
452:   }
453:   if (recorded_dim != expected_dim)
454:   {
455:      snprintf(err, errlen,
456:               "hardened tier: embedding dim mismatch (kb expects %d, schema built for %d)",
457:               expected_dim, recorded_dim);
458:      return -1;
459:   }
460:   /* 2. Schema version: recorded and not older than what this kb depends on. */
461:   {
462:      char e2[256] = "";
463:      aimee_pg_stmt_t *st = aimee_pg_prepare(
464:          conn, "SELECT value FROM kb_meta WHERE key='schema_version'", e2, sizeof e2);
465:      long ver = -1;
466:      if (st && aimee_pg_step(st, e2, sizeof e2) == AIMEE_PG_ROW)
467:      {
468:         const char *v = aimee_pg_column_text(st, 0);
469:         ver = v ? strtol(v, NULL, 10) : -1;
470:      }
471:      if (st)
472:         aimee_pg_finalize(st);
473:      if (ver < 0)
474:      {
475:         snprintf(err, errlen, "hardened tier: no recorded schema_version — schema not migrated");
476:         return -1;
477:      }
478:      if (ver < AIMEE_DB2_SCHEMA_VERSION)
479:      {
480:         snprintf(err, errlen,
481:                  "hardened tier: schema_version %ld is older than the required %d — run the "
482:                  "migration before starting a runtime kb",
483:                  ver, AIMEE_DB2_SCHEMA_VERSION);
484:         return -1;
485:      }
486:   }
487:   /* 3. Representative object presence: a core table, a recent table, and the newest
488:    *    function. to_regclass/to_regprocedure are catalog lookups any role may run;
489:    *    they return NULL for absent objects (never error). */
490:   static const char *const present_checks[] = {
491:       "SELECT (to_regclass('public.kb_documents') IS NOT NULL)::text",
492:       "SELECT (to_regclass('public.kb_vault_witness_checkpoint') IS NOT NULL)::text",
493:       "SELECT (to_regprocedure('public.org_vault_witness_control_fence()') IS NOT NULL)::text",
494:   };
495:   static const char *const present_names[] = {"kb_documents", "kb_vault_witness_checkpoint",
496:                                               "org_vault_witness_control_fence"};
497:   for (size_t i = 0; i < sizeof present_checks / sizeof present_checks[0]; i++)
498:   {
499:      char e2[256] = "";
500:      aimee_pg_stmt_t *st = aimee_pg_prepare(conn, present_checks[i], e2, sizeof e2);
501:      int present = 0;
502:      if (st && aimee_pg_step(st, e2, sizeof e2) == AIMEE_PG_ROW)
503:      {
504:         const char *v = aimee_pg_column_text(st, 0);
505:         present = (v && v[0] == 't');
