591:void db2_lease_begin_at(const char *site)
592:{
593:   pthread_once(&g_thread_conn_key_once, thread_conn_key_init);
594:   /* The init thread is never pooled. */
595:   if (!g_init_thread_set || pthread_equal(pthread_self(), g_init_thread))
596:      return;
597:   if (g_lease_depth++ == 0)
598:   {
599:      /* Outermost scope owns the attribution: a nested begin is served by the
600:       * same connection, so the first caller is the one that must release it. */
601:      g_lease_site = site;
602:      db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
603:      if (!L || !L->conn)
604:         (void)db2_thread_acquire(); /* eager lease for the unit of work */
605:   }
606:}
