41:/* --- mock connection ops ------------------------------------------------- */
42:
43:typedef struct
44:{
45:   int id;
46:   int in_use; /* set while a thread "holds" it — double-lease detector */
47:} mock_conn_t;
48:
49:static int g_open_count = 0;
50:static int g_close_count = 0;
51:static int g_reset_count = 0;
52:static int g_reset_rc = 0; /* set to -1 to force a poison */
53:static pthread_mutex_t g_mock_mtx = PTHREAD_MUTEX_INITIALIZER;
54:
55:static void *mock_open(const char *url, char *e, size_t n)
56:{
57:   (void)url;
58:   (void)e;
59:   (void)n;
60:   mock_conn_t *c = calloc(1, sizeof(*c));
61:   pthread_mutex_lock(&g_mock_mtx);
62:   c->id = ++g_open_count;
63:   pthread_mutex_unlock(&g_mock_mtx);
64:   return c;
65:}
66:static void mock_close(void *p)
67:{
68:   pthread_mutex_lock(&g_mock_mtx);
69:   g_close_count++;
70:   pthread_mutex_unlock(&g_mock_mtx);
71:   free(p);
72:}
73:static int mock_reset(void *p)
74:{
75:   (void)p;
76:   pthread_mutex_lock(&g_mock_mtx);
77:   g_reset_count++;
78:   int rc = g_reset_rc;
79:   pthread_mutex_unlock(&g_mock_mtx);
80:   return rc;
81:}
