136:/* Concurrency: N threads hammer a pool of M < N; assert no connection is ever
137: * handed to two threads at once (the in_use flag) and nothing deadlocks. */
138:#define NTHREADS 16
139:#define POOLM    4
140:#define ITERS    200
141:static volatile int g_conc_fail = 0;
142:
143:static void *worker(void *arg)
144:{
145:   (void)arg;
146:   for (int i = 0; i < ITERS; i++)
147:   {
148:      mock_conn_t *c = (mock_conn_t *)db2_pool_lease(5000);
149:      if (!c)
150:      {
151:         g_conc_fail = 1;
152:         return NULL;
153:      }
154:      /* exclusive ownership check */
155:      if (__sync_lock_test_and_set(&c->in_use, 1) != 0)
156:         g_conc_fail = 1;
157:      /* tiny critical section */
158:      for (volatile int k = 0; k < 50; k++)
159:      {
160:      }
161:      __sync_lock_release(&c->in_use);
162:      db2_pool_return(c);
163:   }
164:   return NULL;
165:}
