228:/* Reaper observability: a lease held past the ceiling (a missed lease_end) is
229: * detected + counted (NOT reclaimed — reclaim-on-death is the WP-B destructor). */
230:static void test_reaper_detects_stuck_lease(void)
231:{
232:   install_mock();
233:   char e[128] = "";
234:   assert(db2_pool_init("mock://x", 2, e, sizeof(e)) == 0);
235:   db2_pool_set_test_ceiling_ms(50);
236:   void *a = db2_pool_lease(1000); /* hold it (simulate missed lease_end) */
237:   assert(a);
238:   assert(db2_pool_reaper_sweep() == 0); /* not yet past ceiling */
239:   usleep(120 * 1000);                   /* exceed the 50ms ceiling */
240:   assert(db2_pool_reaper_sweep() == 1); /* stuck lease flagged */
241:   long stuck = 0;
242:   db2_pool_stats(NULL, NULL, NULL, NULL, NULL, &stuck, NULL);
243:   assert(stuck >= 1);
244:   db2_pool_return(a); /* the connection is NOT corrupted; still usable */
245:   void *b = db2_pool_lease(1000);
246:   assert(b);
247:   db2_pool_return(b);
248:   db2_pool_shutdown();
249:}
