251:/* --- unrecoverable starvation -------------------------------------------- */
252:
253:static char g_starved_reason[256];
254:static int g_starved_calls;
255:static void record_starved(const char *reason)
256:{
257:   g_starved_calls++;
258:   snprintf(g_starved_reason, sizeof(g_starved_reason), "%s", reason ? reason : "");
259:}
260:
261:/* A pool whose every member is stuck past the ceiling WITH callers queued behind
262: * them cannot recover: this pool deliberately never reclaims a live lease, so no
263: * later sweep improves anything. Measured in production as 1096 consecutive
264: * failed health checks over three hours with every member held ~4.5h past a
265: * 5-minute ceiling. The process must give up so a restart policy can fix it. */
266:static void *starve_waiter(void *arg)
267:{
268:   (void)arg;
269:   /* Queues behind the exhausted pool; this is the waiter the policy requires. */
270:   void *c = db2_pool_lease(3000);
271:   if (c)
272:      db2_pool_return(c);
273:   return NULL;
274:}
275:
276:static void test_starved_pool_gives_up_so_it_can_be_restarted(void)
277:{
278:   install_mock();
279:   char e[128] = "";
280:   assert(db2_pool_init("mock://x", 2, e, sizeof(e)) == 0);
281:   db2_pool_set_test_ceiling_ms(50);
282:   db2_pool_set_test_starved_action(record_starved);
283:   g_starved_calls = 0;
284:   g_starved_reason[0] = '\0';
285:
286:   void *a = db2_pool_lease(1000), *b = db2_pool_lease(1000);
287:   assert(a && b); /* every member leased, and never returned */
288:   usleep(120 * 1000);
289:
290:   pthread_t w;
291:   assert(pthread_create(&w, NULL, starve_waiter, NULL) == 0);
292:   usleep(150 * 1000); /* let the waiter queue */
293:
294:   /* One sweep is not enough: a single unlucky sample must not restart a kb. */
295:   for (int i = 0; i < DB2_POOL_STARVED_SWEEPS - 1; i++)
296:   {
297:      (void)db2_pool_reaper_sweep();
298:      assert(g_starved_calls == 0);
299:   }
300:   (void)db2_pool_reaper_sweep();
301:   assert(g_starved_calls == 1);
302:   assert(strstr(g_starved_reason, "lease leak") != NULL);
303:
304:   pthread_join(w, NULL);
305:   db2_pool_return(a);
306:   db2_pool_return(b);
307:   db2_pool_set_test_starved_action(NULL);
308:   db2_pool_shutdown();
309:}
