700: * thin-client push deploy). Bounded by `max_docs` per call so the curator drain
701: * makes steady progress without monopolising. Returns chunks embedded. */
702:int kb_doc_refresh(const char *project, const char *embedding_cmd, int max_docs)
703:{
704:   if (!project || !project[0] || !db2_is_initialized())
705:      return -1;
