713:    * only files with no chunks in kb_documents yet, bounded. */
714:   static const char *sql =
715:       "SELECT f.path, fc.content FROM files f"
716:       " JOIN file_contents fc ON fc.file_id = f.id"
717:       " JOIN projects p ON f.project_id = p.id"
718:       " WHERE p.name = ?1"
719:       "   AND p.lifecycle_state='current'"
720:       "   AND f.generation=p.current_generation"
721:       "   AND (f.path LIKE '%.md' OR f.path LIKE '%.markdown' OR f.path LIKE '%.rst'"
722:       "        OR f.path LIKE '%.txt' OR f.path LIKE '%.adoc' OR f.path LIKE '%.org')"
723:       "   AND NOT EXISTS (SELECT 1 FROM kb_documents kd"
724:       "                   WHERE kd.project=p.name AND kd.generation=p.current_generation"
725:       "                     AND kd.file_path=f.path)"
726:       " LIMIT ?2";
