577:void *db2_conn(void)
578:{
579:   pthread_once(&g_thread_conn_key_once, thread_conn_key_init);
580:   db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
581:   if (L && L->conn)
582:      return L->conn; /* the thread's current lease (re-entrant) */
583:   /* The db2_init() owner thread uses its dedicated g_conn directly. */
584:   if (!g_init_thread_set || pthread_equal(pthread_self(), g_init_thread))
585:      return g_conn;
586:   /* Every other thread leases from the pool (lazily; returned on thread exit
587:    * by the destructor, or sooner via db2_lease_end at a job boundary). */
588:   return db2_thread_acquire();
589:}
