319:   db2_pool_set_test_starved_action(record_starved);
320:   g_starved_calls = 0;
321:
322:   void *a = db2_pool_lease(1000), *b = db2_pool_lease(1000);
323:   assert(a && b);
324:   usleep(120 * 1000); /* past the ceiling, but no waiters */
325:
326:   for (int i = 0; i < DB2_POOL_STARVED_SWEEPS + 2; i++)
327:      (void)db2_pool_reaper_sweep();
328:   assert(g_starved_calls == 0);
