336:/* And the counter resets: a pool that recovers between sweeps must not carry
337: * partial credit toward a later restart. */
338:static void test_starvation_streak_resets_on_recovery(void)
339:{
340:   install_mock();
341:   char e[128] = "";
342:   assert(db2_pool_init("mock://x", 2, e, sizeof(e)) == 0);
343:   db2_pool_set_test_ceiling_ms(50);
344:   db2_pool_set_test_starved_action(record_starved);
345:   g_starved_calls = 0;
346:
347:   void *a = db2_pool_lease(1000), *b = db2_pool_lease(1000);
348:   assert(a && b);
349:   usleep(120 * 1000);
350:   pthread_t w;
351:   assert(pthread_create(&w, NULL, starve_waiter, NULL) == 0);
352:   usleep(150 * 1000);
353:   (void)db2_pool_reaper_sweep(); /* one starved sweep observed */
354:
355:   db2_pool_return(a); /* the leak clears; the waiter is served */
356:   pthread_join(w, NULL);
357:   (void)db2_pool_reaper_sweep(); /* healthy -> streak resets */
358:
359:   /* Starve again: it must take a FULL streak, not one more sweep. */
360:   a = db2_pool_lease(1000);
361:   assert(a);
362:   usleep(120 * 1000);
363:   pthread_t w2;
364:   assert(pthread_create(&w2, NULL, starve_waiter, NULL) == 0);
365:   usleep(150 * 1000);
366:   for (int i = 0; i < DB2_POOL_STARVED_SWEEPS - 1; i++)
367:   {
368:      (void)db2_pool_reaper_sweep();
369:      assert(g_starved_calls == 0);
370:   }
371:   (void)db2_pool_reaper_sweep();
372:   assert(g_starved_calls == 1);
373:
374:   pthread_join(w2, NULL);
375:   db2_pool_return(a);
376:   db2_pool_return(b);
377:   db2_pool_set_test_starved_action(NULL);
378:   db2_pool_shutdown();
379:}
