20:/* Reap `pid` without blocking unbounded: poll waitpid(WNOHANG) for up to
21: * budget_ms. Used after a SIGKILL — a killed process normally dies at once, but
22: * a child wedged in uninterruptible (D) sleep can ignore even SIGKILL; rather
23: * than park the caller forever we give up after the budget (the OS/init reaps
24: * the eventual zombie). Returns 1 if reaped, 0 if it timed out. */
25:static int reap_bounded(pid_t pid, int budget_ms)
26:{
27:   long deadline = now_ms() + budget_ms;
28:   for (;;)
29:   {
30:      pid_t w = waitpid(pid, NULL, WNOHANG);
31:      if (w == pid || w < 0)
32:         return 1;
33:      if (now_ms() >= deadline)
34:         return 0;
35:      struct timespec ts = {.tv_sec = 0, .tv_nsec = 10 * 1000000}; /* 10ms */
36:      nanosleep(&ts, NULL);
37:   }
38:}
