121:   long deadline = (timeout_ms > 0) ? now_ms() + timeout_ms : 0;
122:   int timed_out = 0;
123:   size_t total = 0;
124:   while (total < max_out)
125:   {
126:      int wait_ms = -1; /* block indefinitely when no timeout is set */
127:      if (deadline)
128:      {
129:         long remaining = deadline - now_ms();
130:         if (remaining <= 0)
