132:            timed_out = 1;
133:            break;
134:         }
135:         wait_ms = (remaining > INT_MAX) ? INT_MAX : (int)remaining;
136:      }
137:      struct pollfd pfd = {.fd = pipefd[0], .events = POLLIN};
