165:   close(pipefd[0]);
166:   buf[total] = '\0';
167:   *out_buf = buf;
168:
169:   if (timed_out)
170:   {
171:      /* The command exceeded its wall-clock budget: kill it, reap (bounded — a
172:       * D-state child can ignore SIGKILL; don't park on it), and report a distinct
