177:   }
178:
179:   int status = 0;
180:   if (deadline)
181:   {
182:      /* Keep the deadline live across the reap. The read loop can exit with the
183:       * child still alive — it filled the buffer (total == max_out) or closed
184:       * stdout early (read <= 0) — so an unbounded waitpid here would re-introduce
185:       * the very hang the timeout exists to prevent. Poll-reap until the deadline,
186:       * then kill. */
187:      for (;;)
188:      {
189:         pid_t w = waitpid(pid, &status, WNOHANG);
190:         if (w == pid)
