59: * output (caller frees). */
60:static int run_git(const char *principal, const char *dir, const char *const argv[], int needs_cred,
61:                   char **out)
62:{
63:   /* Resolve credentials vault-first for THIS repo: the per-host vault token for
64:    * the checkout's `origin` host wins over the principal/server identity, so a
65:    * push/fetch to gitlab/gitea authenticates with the right host's stored token
66:    * (not the server's GitHub identity). repo_dir = dir → origin is resolved only
67:    * when a host token is actually needed (fetch/pull/push). */
68:   int token_fd = -1;
69:   char **envp = needs_cred ? git_cred_inject_build_env_for_repo(principal, NULL, dir, NULL,
70:                                                                 environ, &token_fd)
71:                            : NULL;
72:   /* FD mode: the HTTPS token rides an inherited memfd (token_fd), placed at
73:    * GIT_CRED_TOKEN_TARGET_FD in the git child where the askpass reads it — so it
74:    * never lands in the child's /proc/<pid>/environ. The fd is CLOEXEC here, so a
75:    * concurrent exec on another thread can't inherit it. */
76:   int rc = safe_exec_capture_cwd_env_fd_timeout(argv, dir, envp ? envp : environ, out, GO_OUT_MAX,
