1:/* test_git_cred_inject.c — WP-C: a webchat user's git op gets their vaulted
2: * forge token injected into the git child env (GH_TOKEN + GIT_ASKPASS), sourced
3: * autonomously from the sealed vault, with any inherited GH_TOKEN dropped. */
4:#include "git_cred_inject.h"
5:#include "git_forge_vault.h"
6:#include "git_host_cred.h"
7:#include "git_host_resolve.h"
8:#include "git_ssh_agent.h"
9:#include "util.h" /* safe_exec_capture_cwd_env_fd_timeout — fd-mode invariant test */
10:#include "vault_kek_cache.h"
11:#include "vault_service.h"
12:
13:#define STR2(x) #x
14:#define STR(x)  STR2(x)
15:
16:#include <assert.h>
17:#include <stdint.h>
18:#include <stdio.h>
19:#include <stdlib.h>
20:#include <string.h>
21:#include <unistd.h>
22:
23:/* Return the value of `key=` in envp, or NULL; also count matches into *count. */
24:static const char *env_val(char *const *envp, const char *key, int *count)
25:{
26:   size_t kl = strlen(key);
27:   const char *found = NULL;
28:   int n = 0;
29:   for (int i = 0; envp && envp[i]; i++)
30:   {
31:      if (strncmp(envp[i], key, kl) == 0 && envp[i][kl] == '=')
32:      {
33:         found = envp[i] + kl + 1;
34:         n++;
35:      }
36:   }
37:   if (count)
38:      *count = n;
39:   return found;
40:}
41:
42:int main(void)
43:{
44:   char home[256];
45:   snprintf(home, sizeof(home), "/tmp/aimee-gci-test-%d", (int)getpid());
46:   char mk[320];
47:   snprintf(mk, sizeof(mk), "rm -rf %s && mkdir -p %s", home, home);
48:   assert(system(mk) == 0);
49:   setenv("AIMEE_HOME", home, 1);
50:   vault_kek_cache_clear();
51:
52:   const long T0 = 100000;
53:   const char *alice = "webuser:alice";
54:   const char *bob = "webuser:bob";
55:
56:   char *const parent[] = {(char *)"PATH=/usr/bin", (char *)"GH_TOKEN=INHERITED-MUST-BE-DROPPED",
57:                           (char *)"GIT_ASKPASS=/inherited/should/be/dropped",
58:                           (char *)"HOME=/whatever", NULL};
59:
60:   /* No vaulted token yet -> NULL (caller uses ambient creds). */
61:   assert(git_cred_inject_build_env(alice, parent) == NULL);
62:
63:   /* Store alice's PAT in her sealed vault (the WP-B intake path). */
64:   const uint8_t apw[] = "alice-pw";
65:   assert(vault_service_unlock_password(alice, ATTEST_WEBCHAT_TRUSTED, apw, sizeof(apw) - 1, T0) ==
66:          VAULT_OK);
67:   assert(vault_service_set(alice, GIT_FORGE_VAULT_AGENT, GIT_FORGE_TOKEN_CRED, "ghp_aliceSECRET",
68:                            T0) == VAULT_OK);
69:
70:   /* Simulate a background git op: clear the KEK cache so only the server wrap
71:    * can read it — the injected env must STILL carry alice's token. */
72:   vault_kek_cache_clear();
73:   char **env = git_cred_inject_build_env(alice, parent);
74:   assert(env != NULL);
75:
76:   int n = 0;
77:   const char *tok = env_val(env, "GH_TOKEN", &n);
78:   assert(n == 1); /* exactly one GH_TOKEN — the inherited one was dropped */
79:   assert(tok && strcmp(tok, "ghp_aliceSECRET") == 0);
80:
81:   const char *askpass = env_val(env, "GIT_ASKPASS", &n);
82:   assert(n == 1 && askpass && askpass[0] == '/'); /* our shim, not the inherited */
83:   assert(strcmp(askpass, "/inherited/should/be/dropped") != 0);
84:
85:   const char *prompt = env_val(env, "GIT_TERMINAL_PROMPT", &n);
86:   assert(n == 1 && prompt && strcmp(prompt, "0") == 0);
87:
88:   /* PATH/HOME carried through. */
89:   assert(env_val(env, "PATH", &n) && n == 1);
90:   assert(env_val(env, "HOME", &n) && n == 1);
91:
92:   git_cred_inject_free_env(env);
93:
94:   /* Cross-principal: bob has no token -> NULL, never alice's. */
95:   assert(git_cred_inject_build_env(bob, parent) == NULL);
96:
97:   /* Empty / NULL principal -> NULL (no leak). */
98:   assert(git_cred_inject_build_env("", parent) == NULL);
99:
100:   /* --- vault-first precedence for a specific repo (the unified policy) --- */
101:   /* Wire the per-host vault seam and stash a token for a host that is NOT
102:    * alice's personal token, so we can tell which source won. */
103:   git_host_resolve_register(git_host_cred_for_url);
104:   assert(git_host_cred_set("gitlab.example.com", "glpat-HOSTSECRET") == 0);
105:
106:   /* 1) A caller-supplied (inline/broker) token beats every vault source. */
107:   vault_kek_cache_clear();
108:   char **e1 = git_cred_inject_build_env_for_repo(alice, "https://gitlab.example.com/x/y", NULL,
109:                                                  "INLINE-WINS", parent, NULL);
110:   assert(e1 && (tok = env_val(e1, "GH_TOKEN", &n)) && n == 1 && strcmp(tok, "INLINE-WINS") == 0);
111:   git_cred_inject_free_env(e1);
112:
113:   /* 2) The per-host vault token beats alice's own vaulted personal token. */
114:   vault_kek_cache_clear();
115:   char **e2 = git_cred_inject_build_env_for_repo(alice, "https://gitlab.example.com/x/y", NULL,
116:                                                  NULL, parent, NULL);
117:   assert(e2 && (tok = env_val(e2, "GH_TOKEN", &n)) && n == 1 &&
118:          strcmp(tok, "glpat-HOSTSECRET") == 0);
119:   git_cred_inject_free_env(e2);
120:
121:   /* 3) A host with no stored token falls back to alice's personal vault token. */
122:   vault_kek_cache_clear();
123:   char **e3 = git_cred_inject_build_env_for_repo(alice, "https://no-token-host.example/x/y", NULL,
124:                                                  NULL, parent, NULL);
125:   assert(e3 && (tok = env_val(e3, "GH_TOKEN", &n)) && n == 1 &&
126:          strcmp(tok, "ghp_aliceSECRET") == 0);
127:   git_cred_inject_free_env(e3);
128:
129:   /* 4) Seam dormant (unregistered): the per-host step is skipped entirely, so
130:    * even a stored host token is not consulted — falls to the personal token. */
131:   git_host_resolve_register(NULL);
132:   vault_kek_cache_clear();
133:   char **e4 = git_cred_inject_build_env_for_repo(alice, "https://gitlab.example.com/x/y", NULL,
134:                                                  NULL, parent, NULL);
135:   assert(e4 && (tok = env_val(e4, "GH_TOKEN", &n)) && n == 1 &&
136:          strcmp(tok, "ghp_aliceSECRET") == 0);
137:   git_cred_inject_free_env(e4);
138:   git_host_resolve_register(git_host_cred_for_url);
139:
140:   /* --- FD MODE (#3A): the HTTPS token rides an inherited memfd, never the env,
141:    * so it cannot appear in the git child's /proc/<pid>/environ. --- */
142:   {
143:      int tfd = -1;
144:      char **fe = git_cred_inject_build_env_for_repo(alice, "https://github.com/o/r", NULL,
145:                                                     "FD-MODE-SECRET", parent, &tfd);
146:      assert(fe && tfd >= 0);
147:      /* No GH_TOKEN; the fd number is advertised instead (a number, not a secret). */
148:      assert(env_val(fe, "GH_TOKEN", &n) == NULL && n == 0);
149:      const char *fdv = env_val(fe, "AIMEE_GIT_TOKEN_FD", &n);
150:      assert(n == 1 && fdv && atoi(fdv) == GIT_CRED_TOKEN_TARGET_FD);
151:      assert(env_val(fe, "GIT_ASKPASS", &n) && n == 1);
152:      assert(env_val(fe, "GIT_TERMINAL_PROMPT", &n) && n == 1);
153:      /* The secret must not appear ANYWHERE in the env strings. */
154:      for (int i = 0; fe[i]; i++)
155:         assert(strstr(fe[i], "FD-MODE-SECRET") == NULL);
156:
157:      /* The binding invariant: a child exec'd with this env + the inherited fd can
158:       * read the token via /proc/self/fd/<target> (what the askpass does), but the
159:       * token is NOT in its /proc/self/environ. */
160:      const char *argv[] = {
161:          "/bin/sh", "-c",
162:          "cat /proc/self/fd/" STR(
163:              GIT_CRED_TOKEN_TARGET_FD) "; printf '\\n--ENVIRON--\\n'; tr '\\0' '\\n' < "
164:                                        "/proc/self/environ",
165:          NULL};
166:      char *out = NULL;
167:      int rc = safe_exec_capture_cwd_env_fd_timeout(argv, NULL, fe, &out, 1 << 16, 10000, tfd,
168:                                                    GIT_CRED_TOKEN_TARGET_FD);
169:      assert(rc == 0 && out);
170:      char *envmark = strstr(out, "--ENVIRON--");
171:      assert(envmark);
172:      *envmark = '\0'; /* split the capture into [fd read] | [environ dump] */
173:      assert(strstr(out, "FD-MODE-SECRET") != NULL);              /* fd carried the token */
174:      assert(strstr(envmark + 1, "FD-MODE-SECRET") == NULL);      /* NOT in environ */
175:      assert(strstr(envmark + 1, "AIMEE_GIT_TOKEN_FD=") != NULL); /* only the fd number is */
176:      free(out);
177:      close(tfd);
178:      git_cred_inject_free_env(fe);
179:   }
180:
181:   /* SSH integration (WP-C2): a vaulted SSH key adds SSH_AUTH_SOCK to the env
182:    * (the in-memory agent). Guarded on openssh tooling. */
183:   if (system("command -v ssh-agent >/dev/null 2>&1 && command -v ssh-add >/dev/null 2>&1 && "
184:              "command -v ssh-keygen >/dev/null 2>&1") == 0)
185:   {
186:      char rt[300];
187:      snprintf(rt, sizeof(rt), "/dev/shm/aimee-gci-rt-%d", (int)getpid());
188:      setenv("AIMEE_RUNTIME_DIR", rt, 1);
189:      char kf[400], kgen[700];
190:      snprintf(kf, sizeof(kf), "%s/k", home);
191:      snprintf(kgen, sizeof(kgen), "ssh-keygen -q -t ed25519 -N '' -f %s && cat %s", kf, kf);
192:      FILE *p = popen(kgen, "r");
193:      assert(p);
194:      char keybuf[16384];
195:      size_t kl = fread(keybuf, 1, sizeof(keybuf) - 1, p);
196:      keybuf[kl] = '\0';
197:      pclose(p);
198:      /* re-unlock (the earlier cache clear locked alice's vault) before storing */
199:      const uint8_t apw2[] = "alice-pw";
200:      assert(vault_service_unlock_password(alice, ATTEST_WEBCHAT_TRUSTED, apw2, sizeof(apw2) - 1,
201:                                           T0) == VAULT_OK);
202:      assert(vault_service_set(alice, GIT_FORGE_VAULT_AGENT, GIT_FORGE_SSHKEY_CRED, keybuf, T0) ==
203:             VAULT_OK);
204:      char **se = git_cred_inject_build_env(alice, parent);
205:      assert(se != NULL);
206:      const char *sock = env_val(se, "SSH_AUTH_SOCK", &n);
207:      assert(n == 1 && sock && sock[0] == '/'); /* agent socket present */
208:      /* a TOFU SSH command rides alongside so an SSH remote uses the agent key
209:       * and doesn't stall on a first-time host key; known_hosts is pinned to a
210:       * per-principal file (beside the agent socket) so accept-new's first-use
211:       * trust never bleeds through the shared ~/.ssh/known_hosts to other tenants */
212:      const char *sshcmd = env_val(se, "GIT_SSH_COMMAND", &n);
213:      assert(n == 1 && sshcmd && strstr(sshcmd, "StrictHostKeyChecking=accept-new"));
214:      assert(strstr(sshcmd, "UserKnownHostsFile=") && strstr(sshcmd, "/known_hosts"));
215:      assert(strstr(sshcmd, rt)); /* the pinned path is inside THIS principal's runtime dir */
216:      /* the HTTPS token is still injected alongside */
217:      assert(env_val(se, "GH_TOKEN", &n) && n == 1);
218:      git_cred_inject_free_env(se);
219:      git_ssh_agent_stop(alice);
220:      char rmrt[400];
221:      snprintf(rmrt, sizeof(rmrt), "rm -rf %s", rt);
222:      assert(system(rmrt) == 0);
223:      unsetenv("AIMEE_RUNTIME_DIR");
224:   }
225:
226:   char clean[320];
227:   snprintf(clean, sizeof(clean), "rm -rf %s", home);
228:   assert(system(clean) == 0);
229:   printf("git_cred_inject: all tests passed\n");
230:   return 0;
231:}
