81:static const char *jstr(const cJSON *obj, const char *key)
82:{
83:   const cJSON *v = cJSON_GetObjectItemCaseSensitive(obj, key);
84:   return (cJSON_IsString(v) && v->valuestring) ? v->valuestring : NULL;
85:}
