87:/* GitHub + Gitea share the same repo object shape (name/clone_url/ssh_url/private). */
88:static int parse_github_like(const cJSON *arr, cJSON *out)
89:{
90:   if (!cJSON_IsArray(arr))
91:      return -1;
92:   int n = 0;
93:   const cJSON *it = NULL;
94:   cJSON_ArrayForEach(it, arr)
95:   {
96:      const cJSON *priv = cJSON_GetObjectItemCaseSensitive(it, "private");
97:      n += append_repo(out, jstr(it, "name"), jstr(it, "clone_url"), jstr(it, "ssh_url"),
98:                       cJSON_IsTrue(priv));
99:   }
100:   return n;
101:}
