122:/* Bitbucket: { values: [ { name, is_private, links: { clone: [ {name,href} ] } } ] }. */
123:static int parse_bitbucket(const cJSON *root, cJSON *out)
124:{
125:   const cJSON *values = cJSON_GetObjectItemCaseSensitive(root, "values");
126:   if (!cJSON_IsArray(values))
127:      return -1;
128:   int n = 0;
129:   const cJSON *it = NULL;
130:   cJSON_ArrayForEach(it, values)
131:   {
132:      const cJSON *links = cJSON_GetObjectItemCaseSensitive(it, "links");
133:      const cJSON *clone = links ? cJSON_GetObjectItemCaseSensitive(links, "clone") : NULL;
134:      const char *https = NULL, *ssh = NULL;
135:      const cJSON *ln = NULL;
136:      cJSON_ArrayForEach(ln, clone)
137:      {
138:         const char *nm = jstr(ln, "name");
139:         const char *href = jstr(ln, "href");
140:         if (nm && href && strcmp(nm, "https") == 0)
141:            https = href;
142:         else if (nm && href && strcmp(nm, "ssh") == 0)
143:            ssh = href;
144:      }
145:      const cJSON *priv = cJSON_GetObjectItemCaseSensitive(it, "is_private");
146:      n += append_repo(out, jstr(it, "name"), https, ssh, cJSON_IsTrue(priv));
147:   }
148:   return n;
149:}
