151:int git_org_parse(git_org_provider_t p, const char *json, cJSON *out)
152:{
153:   if (!json || !out)
154:      return -1;
155:   cJSON *root = cJSON_Parse(json);
156:   if (!root)
157:      return -1;
158:   int n;
159:   switch (p)
160:   {
161:   case GIT_ORG_GITLAB:
162:      n = parse_gitlab(root, out);
163:      break;
164:   case GIT_ORG_BITBUCKET:
165:      n = parse_bitbucket(root, out);
166:      break;
167:   case GIT_ORG_GITHUB:
168:   case GIT_ORG_GITEA:
169:   default:
170:      n = parse_github_like(root, out);
171:      break;
172:   }
173:   cJSON_Delete(root);
174:   return n;
175:}
