1:/* forge_credentials.c — per-workspace short-lived forge-token broker.
2: * See forge_credentials.h for the contract and the workspace-resource-plane §4
3: * design. Tokens are held in memory only, wiped on revoke, and injected into
4: * the git/gh exec environment (never the command line, never disk). */
5:#include "forge_credentials.h"
6:
7:#include <pthread.h>
8:#include <stdio.h>
9:#include <stdlib.h>
10:#include <string.h>
11:#include <sys/stat.h>
12:
13:/* config_default_dir (config.c): the instance config dir the askpass shim lives
14: * in. Forward-declared to keep this TU off the heavyweight config.h include. */
15:extern const char *config_default_dir(void);
16:
17:#define FORGE_MAX_WS    64
18:#define FORGE_WS_ID_MAX 1024
19:#define FORGE_TOKEN_MAX 4096
20:#define FORGE_SCOPE_MAX 32
21:
22:typedef struct
23:{
24:   int used;
25:   char workspace_id[FORGE_WS_ID_MAX];
26:   char *token; /* heap; explicitly zeroed before free */
27:   char scope[FORGE_SCOPE_MAX];
28:   long expires_epoch; /* now_epoch + ttl at install */
29:} forge_slot_t;
30:
31:static forge_slot_t g_slots[FORGE_MAX_WS];
32:static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
33:
34:/* Zero `n` bytes of `p` so a compiler cannot optimise the wipe away. */
35:static void secure_wipe(void *p, size_t n)
36:{
37:   volatile unsigned char *v = (volatile unsigned char *)p;
38:   while (n--)
39:      *v++ = 0;
40:}
41:
42:static void slot_clear(forge_slot_t *s)
43:{
44:   if (s->token)
45:   {
46:      secure_wipe(s->token, strlen(s->token));
47:      free(s->token);
48:      s->token = NULL;
49:   }
50:   secure_wipe(s->workspace_id, sizeof(s->workspace_id));
51:   secure_wipe(s->scope, sizeof(s->scope));
52:   s->expires_epoch = 0;
53:   s->used = 0;
54:}
55:
56:/* Find the slot for `id`, or NULL. Caller holds g_lock. */
57:static forge_slot_t *slot_find(const char *id)
58:{
59:   for (int i = 0; i < FORGE_MAX_WS; i++)
60:      if (g_slots[i].used && strcmp(g_slots[i].workspace_id, id) == 0)
61:         return &g_slots[i];
62:   return NULL;
63:}
64:
65:static int scope_valid(const char *s)
66:{
67:   return s && (strcmp(s, "global") == 0 || strcmp(s, "workspace") == 0 ||
68:                strcmp(s, "project") == 0 || strcmp(s, "user") == 0);
69:}
70:
71:/* Lattice rank: global (broadest) = 0 … user (narrowest) = 3. -1 if unknown. */
72:static int scope_rank(const char *s)
73:{
74:   if (!s)
75:      return -1;
76:   if (strcmp(s, "global") == 0)
77:      return 0;
78:   if (strcmp(s, "workspace") == 0)
79:      return 1;
80:   if (strcmp(s, "project") == 0)
81:      return 2;
82:   if (strcmp(s, "user") == 0)
83:      return 3;
84:   return -1;
85:}
