87:int forge_cred_install(const char *workspace_id, const char *token, const char *scope,
88:                       long ttl_seconds, long now_epoch)
89:{
90:   if (!workspace_id || !workspace_id[0] || !token || !token[0] || !scope_valid(scope) ||
91:       ttl_seconds <= 0)
92:      return -1;
93:   if (strlen(workspace_id) >= FORGE_WS_ID_MAX || strlen(token) >= FORGE_TOKEN_MAX)
94:      return -1;
95:
96:   char *copy = strdup(token);
97:   if (!copy)
98:      return -1;
99:
100:   pthread_mutex_lock(&g_lock);
101:   forge_slot_t *s = slot_find(workspace_id);
102:   if (!s)
103:   {
104:      for (int i = 0; i < FORGE_MAX_WS; i++)
105:         if (!g_slots[i].used)
106:         {
107:            s = &g_slots[i];
108:            break;
109:         }
110:   }
111:   if (!s)
112:   {
113:      pthread_mutex_unlock(&g_lock);
114:      secure_wipe(copy, strlen(copy));
115:      free(copy);
116:      return -1; /* registry full */
117:   }
118:   /* Replace any existing token in this slot, zeroing the old secret first. */
119:   if (s->token)
120:   {
121:      secure_wipe(s->token, strlen(s->token));
122:      free(s->token);
123:   }
124:   s->used = 1;
125:   snprintf(s->workspace_id, sizeof(s->workspace_id), "%s", workspace_id);
126:   snprintf(s->scope, sizeof(s->scope), "%s", scope);
127:   s->token = copy;
128:   s->expires_epoch = now_epoch + ttl_seconds;
129:   pthread_mutex_unlock(&g_lock);
130:   return 0;
131:}
132:
133:int forge_cred_get(const char *workspace_id, long now_epoch, char *out, size_t out_cap)
134:{
135:   if (out && out_cap)
136:      out[0] = '\0';
137:   if (!workspace_id || !out || out_cap == 0)
138:      return -1;
139:
140:   int rc = -1;
141:   pthread_mutex_lock(&g_lock);
142:   forge_slot_t *s = slot_find(workspace_id);
143:   if (s && s->token && now_epoch < s->expires_epoch)
144:   {
145:      snprintf(out, out_cap, "%s", s->token);
146:      rc = 0;
147:   }
148:   pthread_mutex_unlock(&g_lock);
149:   return rc;
150:}
151:
152:int forge_cred_scope(const char *workspace_id, long now_epoch, char *out, size_t out_cap)
153:{
154:   if (out && out_cap)
155:      out[0] = '\0';
156:   if (!workspace_id || !out || out_cap == 0)
157:      return -1;
158:
159:   int rc = -1;
160:   pthread_mutex_lock(&g_lock);
161:   forge_slot_t *s = slot_find(workspace_id);
162:   if (s && s->token && now_epoch < s->expires_epoch)
163:   {
164:      snprintf(out, out_cap, "%s", s->scope);
165:      rc = 0;
166:   }
167:   pthread_mutex_unlock(&g_lock);
168:   return rc;
169:}
170:
171:int forge_cred_scope_allows(const char *cred_scope, const char *required_scope)
172:{
173:   int c = scope_rank(cred_scope);
174:   int r = scope_rank(required_scope);
175:   if (c < 0 || r < 0)
176:      return 0; /* unknown either side → deny */
177:   /* Broader credential (lower rank) satisfies a narrower requirement. */
178:   return c <= r;
179:}
180:
181:void forge_cred_revoke(const char *workspace_id)
182:{
183:   if (!workspace_id)
184:      return;
185:   pthread_mutex_lock(&g_lock);
186:   forge_slot_t *s = slot_find(workspace_id);
187:   if (s)
188:      slot_clear(s);
189:   pthread_mutex_unlock(&g_lock);
190:}
191:
192:void forge_cred_revoke_all(void)
193:{
194:   pthread_mutex_lock(&g_lock);
195:   for (int i = 0; i < FORGE_MAX_WS; i++)
196:      if (g_slots[i].used)
197:         slot_clear(&g_slots[i]);
198:   pthread_mutex_unlock(&g_lock);
199:}
200:
201:int forge_cred_count(void)
202:{
203:   int n = 0;
204:   pthread_mutex_lock(&g_lock);
205:   for (int i = 0; i < FORGE_MAX_WS; i++)
206:      if (g_slots[i].used)
207:         n++;
208:   pthread_mutex_unlock(&g_lock);
209:   return n;
210:}
