212:/* Build an exec envp from an explicit `token`: a copy of `parent_environ` with
213: * any inherited GH_TOKEN/GITHUB_TOKEN/GIT_ASKPASS dropped, plus GH_TOKEN and
214: * (when `askpass_shim` is set) GIT_ASKPASS + GIT_TERMINAL_PROMPT=0. The token
215: * crosses only into the returned env. Returns malloc'd array or NULL on OOM.
216: * Caller wipes its own copy of `token`. */
217:static char **build_env_from_token(const char *token, char *const *parent_environ,
218:                                   const char *askpass_shim)
219:{
220:   int pn = 0;
221:   if (parent_environ)
222:      while (parent_environ[pn])
223:         pn++;
224:   /* parent entries + GH_TOKEN + (GIT_ASKPASS, GIT_TERMINAL_PROMPT) + NULL */
225:   int extra = askpass_shim && askpass_shim[0] ? 3 : 1;
226:   char **envp = calloc((size_t)pn + extra + 1, sizeof(char *));
227:   if (!envp)
228:      return NULL;
229:   int o = 0;
230:   for (int i = 0; i < pn; i++)
231:   {
232:      /* Drop any inherited GH_TOKEN/GIT_ASKPASS so ours win unambiguously. */
233:      if (strncmp(parent_environ[i], "GH_TOKEN=", 9) == 0 ||
234:          strncmp(parent_environ[i], "GITHUB_TOKEN=", 13) == 0 ||
235:          strncmp(parent_environ[i], "GIT_ASKPASS=", 12) == 0)
236:         continue;
237:      envp[o] = strdup(parent_environ[i]);
238:      if (!envp[o])
239:         goto oom;
240:      o++;
241:   }
242:   {
243:      size_t need = strlen("GH_TOKEN=") + strlen(token) + 1;
244:      char *e = malloc(need);
245:      if (!e)
246:         goto oom;
247:      snprintf(e, need, "GH_TOKEN=%s", token);
248:      envp[o++] = e;
249:   }
