178:      git_cred_inject_free_env(fe);
179:   }
180:
181:   /* SSH integration (WP-C2): a vaulted SSH key adds SSH_AUTH_SOCK to the env
182:    * (the in-memory agent). Guarded on openssh tooling. */
183:   if (system("command -v ssh-agent >/dev/null 2>&1 && command -v ssh-add >/dev/null 2>&1 && "
184:              "command -v ssh-keygen >/dev/null 2>&1") == 0)
185:   {
