40:int safe_exec_capture_cwd_env_fd_timeout(const char *const argv[], const char *cwd,
41:                                         char *const envp[], char **out_buf, size_t max_out,
42:                                         int timeout_ms, int inherit_fd, int target_fd)
43:{
44:   *out_buf = NULL;
45:   if (!argv || !argv[0])
46:      return -1;
47:
48:   int pipefd[2];
49:   if (pipe(pipefd) != 0)
50:      return -1;
51:
52:   pid_t pid = fork();
53:   if (pid < 0)
54:   {
55:      close(pipefd[0]);
56:      close(pipefd[1]);
57:      return -1;
58:   }
59:
60:   if (pid == 0)
61:   {
62:      /* Child: restore a clean signal disposition/mask so the exec'd command
63:       * doesn't inherit the engine's blocked signals (e.g. SIGCHLD/SIGPIPE). */
64:      sigset_t empty;
65:      sigemptyset(&empty);
66:      sigprocmask(SIG_SETMASK, &empty, NULL);
67:      /* redirect stdout/stderr to pipe, close stdin */
68:      close(pipefd[0]);
69:      dup2(pipefd[1], STDOUT_FILENO);
70:      dup2(pipefd[1], STDERR_FILENO);
71:      close(pipefd[1]);
72:      /* Inherit one specific fd (e.g. a memfd holding a credential the askpass
73:       * reads) at a fixed number for the exec'd command, cleared of CLOEXEC. The
74:       * source fd is CLOEXEC in the parent, so a concurrent exec in another
75:       * thread can never leak it — only this child receives it, and only at
76:       * target_fd. */
77:      if (inherit_fd >= 0 && target_fd >= 0)
78:      {
79:         if (inherit_fd != target_fd)
80:         {
81:            if (dup2(inherit_fd, target_fd) < 0) /* dup2 clears CLOEXEC on target_fd */
82:               _exit(127);
83:         }
84:         else if (fcntl(target_fd, F_SETFD, 0) < 0)
85:         {
86:            _exit(127);
87:         }
88:      }
89:      /* Pin the working directory before exec so the command runs in the caller's
90:       * chosen dir (e.g. the work-item repo), not the engine's inherited cwd. A
91:       * failed chdir must NOT silently fall back to the parent cwd. */
92:      if (cwd && cwd[0] && chdir(cwd) != 0)
93:         _exit(127);
94:      /* REPLACE (not augment) the child's environment when envp is given: assigning
95:       * environ makes execvp pass exactly envp, so ONLY envp's entries survive and
96:       * every inherited variable — including engine secrets (AIMEE_APPROVAL_KEY,
97:       * vault tokens) — is dropped. (envp == NULL keeps the inherited environment;
98:       * that path is used by callers that build a full env themselves.) Portable —
99:       * no execvpe needed. */
100:      if (envp)
101:      {
102:         extern char **environ;
103:         environ = (char **)envp;
104:      }
105:      execvp(argv[0], (char *const *)argv);
106:      _exit(127);
107:   }
108:
109:   /* Parent */
110:   close(pipefd[1]);
111:
112:   char *buf = malloc(max_out + 1);
113:   if (!buf)
114:   {
115:      close(pipefd[0]);
116:      kill(pid, SIGKILL);
117:      waitpid(pid, NULL, 0);
118:      return -1;
119:   }
120:
121:   long deadline = (timeout_ms > 0) ? now_ms() + timeout_ms : 0;
122:   int timed_out = 0;
123:   size_t total = 0;
124:   while (total < max_out)
125:   {
126:      int wait_ms = -1; /* block indefinitely when no timeout is set */
127:      if (deadline)
128:      {
129:         long remaining = deadline - now_ms();
130:         if (remaining <= 0)
131:         {
132:            timed_out = 1;
133:            break;
134:         }
135:         wait_ms = (remaining > INT_MAX) ? INT_MAX : (int)remaining;
136:      }
137:      struct pollfd pfd = {.fd = pipefd[0], .events = POLLIN};
138:      int pr = poll(&pfd, 1, wait_ms);
139:      if (pr == 0)
140:      {
141:         timed_out = 1; /* deadline elapsed with no data/EOF */
142:         break;
143:      }
144:      if (pr < 0)
145:      {
146:         if (errno == EINTR)
147:            continue;
148:         break;
149:      }
150:      /* Drain any readable data first; only stop on a hangup/error once the pipe
151:       * has no more bytes (POLLHUP can arrive alongside a final POLLIN). */
152:      if (!(pfd.revents & (POLLIN | POLLHUP | POLLERR)))
153:         continue;
154:      ssize_t n = read(pipefd[0], buf + total, max_out - total);
155:      if (n < 0)
156:      {
157:         if (errno == EINTR)
158:            continue; /* interrupted before any byte — retry, don't drop output */
159:         break;       /* real read error */
160:      }
161:      if (n == 0)
162:         break; /* EOF: child closed stdout / exited */
163:      total += (size_t)n;
164:   }
165:   close(pipefd[0]);
166:   buf[total] = '\0';
167:   *out_buf = buf;
168:
169:   if (timed_out)
170:   {
171:      /* The command exceeded its wall-clock budget: kill it, reap (bounded — a
172:       * D-state child can ignore SIGKILL; don't park on it), and report a distinct
173:       * timeout failure so callers don't park the engine on a hang. */
174:      kill(pid, SIGKILL);
175:      reap_bounded(pid, 2000);
176:      return SAFE_EXEC_TIMEOUT;
177:   }
178:
179:   int status = 0;
180:   if (deadline)
181:   {
182:      /* Keep the deadline live across the reap. The read loop can exit with the
183:       * child still alive — it filled the buffer (total == max_out) or closed
184:       * stdout early (read <= 0) — so an unbounded waitpid here would re-introduce
185:       * the very hang the timeout exists to prevent. Poll-reap until the deadline,
186:       * then kill. */
187:      for (;;)
188:      {
189:         pid_t w = waitpid(pid, &status, WNOHANG);
190:         if (w == pid)
191:            break; /* reaped normally */
192:         if (w < 0)
193:            /* Can't determine the child's status (e.g. ECHILD — externally
194:             * reaped): report failure rather than a false success. */
195:            return -1;
196:         if (now_ms() >= deadline)
197:         {
198:            kill(pid, SIGKILL);
199:            reap_bounded(pid, 2000);
200:            return SAFE_EXEC_TIMEOUT;
201:         }
202:         struct timespec ts = {.tv_sec = 0, .tv_nsec = 10 * 1000000}; /* 10ms */
203:         nanosleep(&ts, NULL);
204:      }
205:   }
206:   else
207:   {
208:      waitpid(pid, &status, 0);
209:   }
210:   return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
211:}
