126:int git_project_canonical_remote(const char *url, char *out, size_t cap)
127:{
128:   if (!url || !url[0] || !out || cap == 0)
129:      return -1;
130:   char *norm = util_url_normalize(url);
131:   const char *u = norm ? norm : url;
132:   /* Strip userinfo: scheme://user:pass@host/... -> scheme://host/... — the
133:    * canonical remote is CREDENTIAL-FREE by contract; it is stored in sidecars
134:    * and echoed in responses/logs. */
135:   const char *scheme_end = strstr(u, "://");
136:   char buf[GP_PATH_MAX];
137:   if (scheme_end)
138:   {
139:      const char *host = scheme_end + 3;
140:      const char *slash = strchr(host, '/');
141:      const char *at = memchr(host, '@', slash ? (size_t)(slash - host) : strlen(host));
142:      if (at)
143:         snprintf(buf, sizeof(buf), "%.*s%s", (int)(scheme_end + 3 - u), u, at + 1);
144:      else
145:         snprintf(buf, sizeof(buf), "%s", u);
146:   }
147:   else
148:      snprintf(buf, sizeof(buf), "%s", u);
149:   free(norm);
150:   /* Strip query/fragment and a trailing ".git" / trailing slashes. */
151:   buf[strcspn(buf, "?#")] = '\0';
152:   size_t bl = strlen(buf);
153:   while (bl > 0 && buf[bl - 1] == '/')
154:      buf[--bl] = '\0';
155:   if (bl > 4 && strcmp(buf + bl - 4, ".git") == 0)
156:      buf[bl - 4] = '\0';
157:   if (!buf[0] || strchr(buf, ' ') || strchr(buf, '\n'))
158:      return -1;
159:   snprintf(out, cap, "%s", buf);
160:   return 0;
161:}
