87:int forge_cred_install(const char *workspace_id, const char *token, const char *scope,
88:                       long ttl_seconds, long now_epoch)
89:{
90:   if (!workspace_id || !workspace_id[0] || !token || !token[0] || !scope_valid(scope) ||
91:       ttl_seconds <= 0)
92:      return -1;
93:   if (strlen(workspace_id) >= FORGE_WS_ID_MAX || strlen(token) >= FORGE_TOKEN_MAX)
94:      return -1;
95:
96:   char *copy = strdup(token);
97:   if (!copy)
98:      return -1;
99:
100:   pthread_mutex_lock(&g_lock);
101:   forge_slot_t *s = slot_find(workspace_id);
102:   if (!s)
103:   {
104:      for (int i = 0; i < FORGE_MAX_WS; i++)
105:         if (!g_slots[i].used)
106:         {
107:            s = &g_slots[i];
108:            break;
109:         }
110:   }
111:   if (!s)
112:   {
113:      pthread_mutex_unlock(&g_lock);
114:      secure_wipe(copy, strlen(copy));
115:      free(copy);
116:      return -1; /* registry full */
117:   }
118:   /* Replace any existing token in this slot, zeroing the old secret first. */
119:   if (s->token)
120:   {
121:      secure_wipe(s->token, strlen(s->token));
122:      free(s->token);
123:   }
124:   s->used = 1;
125:   snprintf(s->workspace_id, sizeof(s->workspace_id), "%s", workspace_id);
126:   snprintf(s->scope, sizeof(s->scope), "%s", scope);
127:   s->token = copy;
128:   s->expires_epoch = now_epoch + ttl_seconds;
129:   pthread_mutex_unlock(&g_lock);
130:   return 0;
131:}
