171:int forge_cred_scope_allows(const char *cred_scope, const char *required_scope)
172:{
173:   int c = scope_rank(cred_scope);
174:   int r = scope_rank(required_scope);
175:   if (c < 0 || r < 0)
176:      return 0; /* unknown either side → deny */
177:   /* Broader credential (lower rank) satisfies a narrower requirement. */
178:   return c <= r;
179:}
