26:git_org_provider_t git_org_detect(const char *host)
27:{
28:   if (!host || !host[0])
29:      return GIT_ORG_UNKNOWN;
30:   /* Case-insensitive substring hints; default self-hosted to the Gitea shape. */
31:   char h[256];
32:   size_t i = 0;
33:   for (; host[i] && i < sizeof(h) - 1; i++)
34:      h[i] = (char)tolower((unsigned char)host[i]);
35:   h[i] = '\0';
36:   if (strstr(h, "github"))
37:      return GIT_ORG_GITHUB;
38:   if (strstr(h, "gitlab"))
39:      return GIT_ORG_GITLAB;
40:   if (strstr(h, "bitbucket"))
41:      return GIT_ORG_BITBUCKET;
42:   return GIT_ORG_GITEA;
43:}
