62:/* Append {name, clone_url, ssh_url, private} to `out`, skipping an entry missing a
63: * name or an HTTPS clone URL. Returns 1 if appended, else 0. */
64:static int append_repo(cJSON *out, const char *name, const char *clone_url, const char *ssh_url,
65:                       int is_private)
66:{
67:   if (!name || !name[0] || !clone_url || !clone_url[0])
68:      return 0;
69:   cJSON *o = cJSON_CreateObject();
70:   if (!o)
71:      return 0;
72:   cJSON_AddStringToObject(o, "name", name);
73:   cJSON_AddStringToObject(o, "clone_url", clone_url);
74:   if (ssh_url && ssh_url[0])
75:      cJSON_AddStringToObject(o, "ssh_url", ssh_url);
76:   cJSON_AddBoolToObject(o, "private", is_private ? 1 : 0);
77:   cJSON_AddItemToArray(out, o);
78:   return 1;
79:}
