103:/* GitLab projects: http_url_to_repo / ssh_url_to_repo, visibility != "public". */
104:static int parse_gitlab(const cJSON *arr, cJSON *out)
105:{
106:   if (!cJSON_IsArray(arr))
107:      return -1;
108:   int n = 0;
109:   const cJSON *it = NULL;
110:   cJSON_ArrayForEach(it, arr)
111:   {
112:      const char *vis = jstr(it, "visibility");
113:      const char *name = jstr(it, "path");
114:      if (!name)
115:         name = jstr(it, "name");
116:      n += append_repo(out, name, jstr(it, "http_url_to_repo"), jstr(it, "ssh_url_to_repo"),
117:                       vis ? strcmp(vis, "public") != 0 : 0);
118:   }
119:   return n;
120:}
