177:/* An owner/host slug is interpolated into a URL + headers, so validate strictly:
178: * host allows alnum, '.', '-', ':'; owner allows alnum, '.', '_', '-'. */
179:static int host_ok(const char *s)
180:{
181:   if (!s || !s[0] || strlen(s) > 200)
182:      return 0;
183:   for (const char *p = s; *p; p++)
184:      if (!(isalnum((unsigned char)*p) || *p == '.' || *p == '-' || *p == ':'))
185:         return 0;
186:   return 1;
187:}
188:static int owner_ok(const char *s)
189:{
190:   if (!s || !s[0] || strlen(s) > 128)
191:      return 0;
192:   for (const char *p = s; *p; p++)
193:      if (!(isalnum((unsigned char)*p) || *p == '.' || *p == '_' || *p == '-'))
194:         return 0;
195:   return 1;
196:}
