198:/* Fetch + parse every page for one endpoint whose URL up to (but not including)
199: * the page number is `url_base` (already carrying a '?...' query with the page-size
200: * param). Appends to `out`. Returns 200 (ok, appended), 404 (endpoint absent and
201: * nothing appended), 401 (unauthorized), or 502 (upstream/parse failure). */
202:static int fetch_pages(git_org_provider_t p, const char *url_base, const char *pageparam,
203:                       int page_size, const char *headers, cJSON *out, char *err, size_t errlen)
204:{
205:   int appended_total = 0;
206:   for (int page = 1; page <= MAX_PAGES; page++)
207:   {
208:      char url[1200];
209:      if (snprintf(url, sizeof(url), "%s&%s=%d", url_base, pageparam, page) >= (int)sizeof(url))
210:         return appended_total > 0 ? 200 : 502;
211:      char *resp = NULL;
212:      int st = agent_http_get(url, headers, &resp, HTTP_TIMEOUT_MS);
213:      if (st == 404)
214:      {
215:         free(resp);
216:         return appended_total > 0 ? 200 : 404;
217:      }
218:      if (st == 401 || st == 403)
219:      {
220:         free(resp);
221:         snprintf(err, errlen, "not authorized for that owner — add a token for this host");
222:         return 401;
223:      }
224:      if (st != 200 || !resp)
225:      {
226:         free(resp);
227:         if (appended_total > 0)
228:            return 200;
229:         snprintf(err, errlen, "could not reach the git host (status %d)", st);
230:         return 502;
231:      }
232:      int n = git_org_parse(p, resp, out);
233:      free(resp);
234:      if (n < 0)
235:      {
236:         if (appended_total > 0)
237:            return 200;
238:         snprintf(err, errlen, "unexpected response from the git host");
239:         return 502;
240:      }
241:      appended_total += n;
242:      if (n < page_size || cJSON_GetArraySize(out) >= MAX_REPOS)
243:         break; /* short page ⇒ last page */
244:   }
245:   return 200;
246:}
