248:int git_org_repos_list(const char *host, const char *owner, cJSON **out, char *provider,
249:                       size_t provider_cap, char *err, size_t errlen)
250:{
251:   if (out)
252:      *out = NULL;
253:   if (err && errlen)
254:      err[0] = '\0';
255:   if (!out || !host_ok(host) || !owner_ok(owner))
256:   {
257:      if (err)
258:         snprintf(err, errlen, "host and owner are required");
259:      return 400;
260:   }
261:   git_org_provider_t p = git_org_detect(host);
262:
263:   /* Resolve the per-host token (write-only vault); enumerate unauthenticated when
264:    * none is stored (works for public orgs). */
265:   char tok[1024];
266:   int have_tok = git_host_cred_get(host, tok, sizeof(tok)) == 1 && tok[0];
267:
268:   /* Per-provider request headers (newline-separated; agent_bridge splits on \n). */
269:   char headers[1400];
270:   switch (p)
271:   {
272:   case GIT_ORG_GITHUB:
273:      snprintf(headers, sizeof(headers),
274:               "Accept: application/vnd.github+json\nUser-Agent: aimee-server\n"
275:               "X-GitHub-Api-Version: 2022-11-28%s%s",
276:               have_tok ? "\nAuthorization: Bearer " : "", have_tok ? tok : "");
277:      break;
278:   case GIT_ORG_GITLAB:
279:      if (have_tok)
280:         snprintf(headers, sizeof(headers), "PRIVATE-TOKEN: %s", tok);
281:      else
282:         headers[0] = '\0';
283:      break;
284:   case GIT_ORG_BITBUCKET:
285:      snprintf(headers, sizeof(headers), "User-Agent: aimee-server%s%s",
286:               have_tok ? "\nAuthorization: Bearer " : "", have_tok ? tok : "");
287:      break;
288:   case GIT_ORG_GITEA:
289:   default:
290:      if (have_tok)
291:         snprintf(headers, sizeof(headers), "Authorization: token %s", tok);
292:      else
293:         headers[0] = '\0';
294:      break;
295:   }
296:
297:   /* Build the org (primary) + user (fallback) endpoint bases + page param. */
298:   char org_base[900] = "", user_base[900] = "";
299:   const char *pageparam = "page";
300:   int page_size = ORG_PER_PAGE;
301:   switch (p)
302:   {
303:   case GIT_ORG_GITHUB:
304:      snprintf(org_base, sizeof(org_base), "https://api.github.com/orgs/%s/repos?per_page=%d",
305:               owner, ORG_PER_PAGE);
306:      snprintf(user_base, sizeof(user_base), "https://api.github.com/users/%s/repos?per_page=%d",
307:               owner, ORG_PER_PAGE);
308:      break;
309:   case GIT_ORG_GITLAB:
310:   {
311:      /* gitlab.com or a self-hosted host; both serve /api/v4. */
312:      snprintf(org_base, sizeof(org_base), "https://%s/api/v4/groups/%s/projects?per_page=%d", host,
313:               owner, ORG_PER_PAGE);
314:      snprintf(user_base, sizeof(user_base), "https://%s/api/v4/users/%s/projects?per_page=%d",
315:               host, owner, ORG_PER_PAGE);
316:      break;
317:   }
318:   case GIT_ORG_BITBUCKET:
319:      snprintf(org_base, sizeof(org_base),
320:               "https://api.bitbucket.org/2.0/repositories/%s?pagelen=%d", owner, ORG_PER_PAGE);
321:      /* Bitbucket has no org/user split. */
322:      break;
323:   case GIT_ORG_GITEA:
324:   default:
325:      page_size = GITEA_LIMIT;
326:      snprintf(org_base, sizeof(org_base), "https://%s/api/v1/orgs/%s/repos?limit=%d", host, owner,
327:               GITEA_LIMIT);
328:      snprintf(user_base, sizeof(user_base), "https://%s/api/v1/users/%s/repos?limit=%d", host,
329:               owner, GITEA_LIMIT);
330:      break;
331:   }
332:
333:   cJSON *arr = cJSON_CreateArray();
334:   if (!arr)
335:   {
336:      snprintf(err, errlen, "out of memory");
337:      return 502;
338:   }
339:
340:   int st = fetch_pages(p, org_base, pageparam, page_size, headers, arr, err, errlen);
341:   /* An org-endpoint 404 means the owner is likely a user (or a self-hosted user
342:    * account) — retry the user endpoint where the provider has one. */
343:   if (st == 404 && user_base[0])
344:      st = fetch_pages(p, user_base, pageparam, page_size, headers, arr, err, errlen);
345:
346:   if (st != 200)
347:   {
348:      cJSON_Delete(arr);
349:      if (st == 404 && err && errlen)
350:         snprintf(err, errlen, "no repositories found for that owner");
351:      return st;
352:   }
353:
354:   if (provider && provider_cap)
355:      snprintf(provider, provider_cap, "%s", git_org_provider_name(p));
356:   *out = arr;
357:   return 0;
358:}

