156:void *db2_pool_lease(int timeout_ms)
157:{
158:   if (timeout_ms <= 0)
159:      timeout_ms = DB2_POOL_DEFAULT_LEASE_TIMEOUT_MS;
160:   struct timespec deadline;
161:   clock_gettime(CLOCK_REALTIME, &deadline);
162:   deadline.tv_sec += timeout_ms / 1000;
163:   deadline.tv_nsec += (long)(timeout_ms % 1000) * 1000000L;
164:   if (deadline.tv_nsec >= 1000000000L)
165:   {
166:      deadline.tv_sec += 1;
167:      deadline.tv_nsec -= 1000000000L;
168:   }
169:
170:   pthread_mutex_lock(&g_mtx);
171:   for (;;)
172:   {
173:      if (!g_active)
174:      {
175:         pthread_mutex_unlock(&g_mtx);
176:         return NULL;
177:      }
178:      /* 1) hand out an already-open free member. */
179:      for (int i = 0; i < g_size; i++)
180:      {
181:         if (!g_members[i].leased && g_members[i].conn)
182:         {
183:            g_members[i].leased = 1;
184:            g_members[i].site = NULL;
185:            g_members[i].owner = pthread_self();
186:            g_members[i].lease_ms = mono_ms();
187:            g_grants++;
188:            void *c = g_members[i].conn;
189:            pthread_mutex_unlock(&g_mtx);
190:            return c;
191:         }
192:      }
193:      /* 2) grow: open an unused slot on demand (under the lock — warm-up only,
194:       * at most `size` times for the pool's life). */
195:      int slot = -1;
196:      for (int i = 0; i < g_size; i++)
197:         if (!g_members[i].conn && !g_members[i].leased)
198:         {
199:            slot = i;
200:            break;
201:         }
202:      if (slot >= 0)
203:      {
204:         char e[256] = "";
205:         void *c = g_open(g_url, e, sizeof(e));
206:         if (c)
207:         {
208:            g_members[slot].conn = c;
209:            g_members[slot].leased = 1;
210:            g_members[slot].site = NULL;
211:            g_members[slot].owner = pthread_self();
212:            g_members[slot].lease_ms = mono_ms();
213:            g_grants++;
214:            pthread_mutex_unlock(&g_mtx);
215:            return c;
216:         }
217:         POOL_LOG("on-demand member open failed: %s", e[0] ? e : "unknown");
218:         /* fall through to the bounded wait rather than busy-retrying open */
219:      }
220:      /* 3) at the cap and all leased -> bounded wait. */
221:      g_waiters++;
222:      int rc = pthread_cond_timedwait(&g_cond, &g_mtx, &deadline);
223:      g_waiters--;
224:      if (rc == ETIMEDOUT)
225:      {
226:         g_timeouts++;
227:         pthread_mutex_unlock(&g_mtx);
228:         POOL_LOG("lease timeout (%d ms); pool exhausted (cap=%d)", timeout_ms, g_size);
229:         return NULL;
230:      }
231:   }
232:}
