443:      snprintf(err, errlen, "hardened tier: could not read the recorded embedding dim");
444:      return -1;
445:   }
446:   if (rd != DB2_DIM_FOUND)
447:   {
448:      snprintf(err, errlen,
449:               "hardened tier: schema is not migrated (no recorded embedding dim). A "
450:               "runtime-role kb cannot apply the schema — run the owner/migrate step first.");
451:      return -1;
452:   }
453:   if (recorded_dim != expected_dim)
454:   {
455:      snprintf(err, errlen,
456:               "hardened tier: embedding dim mismatch (kb expects %d, schema built for %d)",
457:               expected_dim, recorded_dim);
458:      return -1;
459:   }
460:   /* 2. Schema version: recorded and not older than what this kb depends on. */
461:   {
462:      char e2[256] = "";
463:      aimee_pg_stmt_t *st = aimee_pg_prepare(
464:          conn, "SELECT value FROM kb_meta WHERE key='schema_version'", e2, sizeof e2);
465:      long ver = -1;
466:      if (st && aimee_pg_step(st, e2, sizeof e2) == AIMEE_PG_ROW)
