100:int db2_pool_init(const char *libpq_url, int size, char *errbuf, size_t errbuf_len)
101:{
102:   if (!libpq_url || !libpq_url[0])
103:   {
104:      if (errbuf && errbuf_len)
105:         snprintf(errbuf, errbuf_len, "db2_pool: empty libpq url");
106:      return -1;
107:   }
108:   pthread_mutex_lock(&g_mtx);
109:   if (g_active)
110:   {
111:      int same = (strcmp(g_url, libpq_url) == 0);
112:      pthread_mutex_unlock(&g_mtx);
113:      return same ? 0 : -1;
114:   }
115:   (void)errbuf;
116:   (void)errbuf_len;
117:   if (size < 1)
118:      size = 1;
119:   if (size > DB2_POOL_MAX_SIZE)
120:      size = DB2_POOL_MAX_SIZE;
121:   snprintf(g_url, sizeof(g_url), "%s", libpq_url);
122:   /* Counters are per-pool-lifetime. */
123:   g_grants = g_timeouts = g_stuck = g_poisoned = 0;
124:   /* Lazy pool: members are opened on first lease, up to `size`. Keeps db2_init
125:    * cheap (it opens only its own connection) and avoids holding idle
126:    * connections the deployment never needs. */
127:   for (int i = 0; i < size; i++)
128:   {
129:      g_members[i].conn = NULL;
130:      g_members[i].leased = 0;
131:      g_members[i].lease_ms = 0;
132:      g_members[i].last_reopen = 0;
133:   }
134:   g_size = size; /* the cap */
135:   g_active = 1;
136:   pthread_mutex_unlock(&g_mtx);
137:
138:   g_reaper_stop = 0;
139:   if (pthread_create(&g_reaper_thread, NULL, db2_pool_reaper_main, NULL) == 0)
140:      g_reaper_running = 1;
141:   else
142:      POOL_LOG("reaper thread failed to start; leak-reclaim disabled");
143:
144:   POOL_LOG("initialized: up to %d connections (opened on demand)", size);
145:   return 0;
146:}
