167:static void test_concurrency_no_double_lease(void)
168:{
169:   install_mock();
170:   char e[128] = "";
171:   assert(db2_pool_init("mock://x", POOLM, e, sizeof(e)) == 0);
172:   pthread_t th[NTHREADS];
173:   for (int i = 0; i < NTHREADS; i++)
174:      assert(pthread_create(&th[i], NULL, worker, NULL) == 0);
175:   for (int i = 0; i < NTHREADS; i++)
176:      pthread_join(th[i], NULL);
177:   assert(g_conc_fail == 0); /* no double-lease, no timeout-starvation */
178:   long grants = 0;
179:   db2_pool_stats(NULL, NULL, NULL, &grants, NULL, NULL, NULL);
180:   assert(grants == (long)NTHREADS * ITERS);
181:   db2_pool_shutdown();
182:}
