228:/* Reaper observability: a lease held past the ceiling (a missed lease_end) is
229: * detected + counted (NOT reclaimed — reclaim-on-death is the WP-B destructor). */
230:static void test_reaper_detects_stuck_lease(void)
231:{
232:   install_mock();
