237:   assert(a);
238:   assert(db2_pool_reaper_sweep() == 0); /* not yet past ceiling */
239:   usleep(120 * 1000);                   /* exceed the 50ms ceiling */
240:   assert(db2_pool_reaper_sweep() == 1); /* stuck lease flagged */
241:   long stuck = 0;
242:   db2_pool_stats(NULL, NULL, NULL, NULL, NULL, &stuck, NULL);
