251:/* --- unrecoverable starvation -------------------------------------------- */
252:
253:static char g_starved_reason[256];
254:static int g_starved_calls;
255:static void record_starved(const char *reason)
256:{
257:   g_starved_calls++;
258:   snprintf(g_starved_reason, sizeof(g_starved_reason), "%s", reason ? reason : "");
259:}
260:
261:/* A pool whose every member is stuck past the ceiling WITH callers queued behind
262: * them cannot recover: this pool deliberately never reclaims a live lease, so no
263: * later sweep improves anything. Measured in production as 1096 consecutive
264: * failed health checks over three hours with every member held ~4.5h past a
265: * 5-minute ceiling. The process must give up so a restart policy can fix it. */
266:static void *starve_waiter(void *arg)
267:{
268:   (void)arg;
269:   /* Queues behind the exhausted pool; this is the waiter the policy requires. */
270:   void *c = db2_pool_lease(3000);
271:   if (c)
272:      db2_pool_return(c);
273:   return NULL;
274:}
