93:static int64_t mono_ms(void)
94:{
95:   struct timespec ts;
96:   clock_gettime(CLOCK_MONOTONIC, &ts);
97:   return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
