283:void db2_pool_discard(void *conn)
284:{
285:   if (!conn)
286:      return;
287:   pthread_mutex_lock(&g_mtx);
288:   int i = member_index_locked(conn);
289:   if (i < 0)
290:   {
291:      pthread_mutex_unlock(&g_mtx);
292:      g_close(conn);
293:      return;
294:   }
295:   g_close(g_members[i].conn);
296:   g_members[i].conn = NULL;
297:   int64_t now = mono_ms();
298:   char e[256] = "";
299:   if (now - g_members[i].last_reopen >= DB2_POOL_REOPEN_MIN_MS)
300:   {
301:      g_members[i].conn = g_open(g_url, e, sizeof(e));
302:      g_members[i].last_reopen = now;
303:   }
304:   g_members[i].leased = 0;
305:   g_members[i].lease_ms = 0;
306:   g_poisoned++;
307:   if (!g_members[i].conn)
