627:void db2_lease_release_idle(void)
628:{
629:   /* Release a connection acquired lazily by db2_conn() OUTSIDE any
630:    * db2_lease_begin/_end scope (depth 0). Long-lived periodic workers (curator
631:    * drain, maintenance timer) otherwise pin a pool connection for their whole
632:    * lifetime — the reaper flags it as a stuck lease and it permanently shrinks
633:    * the pool. They call this at a job boundary (between cycles) to return the
634:    * connection while idle. No-op inside a lease scope or on the init thread. */
635:   if (!g_init_thread_set || pthread_equal(pthread_self(), g_init_thread))
636:      return;
637:   if (g_lease_depth != 0)
638:      return; /* inside an explicit begin/end unit — leave it owned */
639:   db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
640:   if (L && L->conn)
641:   {
642:      if (L->pooled)
643:         db2_pool_return(L->conn);
644:      else
645:         aimee_pg_close(L->conn);
646:      L->conn = NULL;
647:      L->pooled = 0;
648:   }
649:}
