591:void db2_lease_begin_at(const char *site)
592:{
593:   pthread_once(&g_thread_conn_key_once, thread_conn_key_init);
594:   /* The init thread is never pooled. */
595:   if (!g_init_thread_set || pthread_equal(pthread_self(), g_init_thread))
596:      return;
597:   if (g_lease_depth++ == 0)
598:   {
599:      /* Outermost scope owns the attribution: a nested begin is served by the
600:       * same connection, so the first caller is the one that must release it. */
601:      g_lease_site = site;
602:      db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
603:      if (!L || !L->conn)
604:         (void)db2_thread_acquire(); /* eager lease for the unit of work */
605:   }
606:}
607:
608:void db2_lease_end(void)
609:{
610:   if (!g_init_thread_set || pthread_equal(pthread_self(), g_init_thread))
611:      return;
612:   if (g_lease_depth > 0 && --g_lease_depth == 0)
613:   {
614:      db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
615:      if (L && L->conn)
616:      {
617:         if (L->pooled)
618:            db2_pool_return(L->conn);
619:         else
620:            aimee_pg_close(L->conn);
621:         L->conn = NULL;
622:         L->pooled = 0;
623:      }
624:   }
625:}
626:
627:void db2_lease_release_idle(void)
628:{
629:   /* Release a connection acquired lazily by db2_conn() OUTSIDE any
630:    * db2_lease_begin/_end scope (depth 0). Long-lived periodic workers (curator
631:    * drain, maintenance timer) otherwise pin a pool connection for their whole
632:    * lifetime — the reaper flags it as a stuck lease and it permanently shrinks
633:    * the pool. They call this at a job boundary (between cycles) to return the
634:    * connection while idle. No-op inside a lease scope or on the init thread. */
635:   if (!g_init_thread_set || pthread_equal(pthread_self(), g_init_thread))
636:      return;
637:   if (g_lease_depth != 0)
638:      return; /* inside an explicit begin/end unit — leave it owned */
639:   db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
640:   if (L && L->conn)
641:   {
642:      if (L->pooled)
643:         db2_pool_return(L->conn);
644:      else
645:         aimee_pg_close(L->conn);
646:      L->conn = NULL;
647:      L->pooled = 0;
648:   }
649:}
