651:void *db2_thread_conn_open(char *errbuf, size_t errlen)
652:{
653:   pthread_once(&g_thread_conn_key_once, thread_conn_key_init);
654:   const char *url = g_pg_url[0] ? g_pg_url : NULL;
655:   if (!url)
656:   {
657:      if (errbuf && errlen)
658:         snprintf(errbuf, errlen, "db2 not initialized");
659:      return NULL;
660:   }
661:   void *conn = aimee_pg_open(url, errbuf, errlen);
662:   if (!conn)
663:      return NULL;
664:   db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
665:   if (!L)
666:   {
667:      L = (db2_thread_lease_t *)calloc(1, sizeof(*L));
668:      if (!L)
669:      {
670:         aimee_pg_close(conn);
671:         return NULL;
672:      }
673:      if (pthread_setspecific(g_thread_conn_key, L) != 0)
674:      {
675:         free(L);
676:         aimee_pg_close(conn);
677:         return NULL;
678:      }
679:   }
680:   if (L->conn)
681:   {
682:      if (L->pooled)
683:         db2_pool_return(L->conn);
684:      else
685:         aimee_pg_close(L->conn);
686:   }
687:   L->conn = conn;
688:   L->pooled = 0;
689:   return conn;
690:}

