240:/* Acquire the dim-bootstrap advisory lock, polling pg_try_advisory_lock every
241: * ~250ms up to budget_ms. Returns 0 = acquired, 1 = timed out (another session
242: * holds it for the whole budget), -1 = query error. *elapsed_ms (optional) gets
243: * the wall time spent so the caller can subtract it from the probe budget. On the
244: * sqlite test shim there is no advisory lock (single-process tests) → acquired. */
245:static int db2_dim_lock_acquire(void *conn, int budget_ms, int *elapsed_ms)
246:{
247:   long start = db2_mono_ms();
248:   if (aimee_pg_is_shim())
249:   {
250:      if (elapsed_ms)
251:         *elapsed_ms = 0;
252:      return 0;
253:   }
254:   for (;;)
255:   {
256:      char err[256] = "";
257:      /* ::int — pg_try_advisory_lock returns BOOLEAN; aimee_pg_column_int does
258:       * atoi(PQgetvalue) and atoi("t")==0, so the bool must be cast to 1/0 text or
259:       * the lock would never read as acquired. */
260:      aimee_pg_stmt_t *st = aimee_pg_prepare(conn, "SELECT pg_try_advisory_lock(hashtext(?1))::int",
261:                                             err, sizeof(err));
262:      int got = 0, ok = 0;
263:      if (st)
264:      {
265:         aimee_pg_bind_text(st, "?1", DB2_DIM_LOCK_KEY);
266:         if (aimee_pg_step(st, err, sizeof(err)) == AIMEE_PG_ROW)
267:         {
268:            ok = 1;
269:            got = aimee_pg_column_int(st, 0) ? 1 : 0;
270:         }
271:         aimee_pg_finalize(st);
272:      }
273:      int spent = (int)(db2_mono_ms() - start);
274:      if (elapsed_ms)
275:         *elapsed_ms = spent;
276:      if (!ok)
277:         return -1;
278:      if (got)
279:         return 0;
280:      if (spent >= budget_ms)
281:         return 1;
282:      struct timespec ts = {0, 250L * 1000 * 1000};
283:      nanosleep(&ts, NULL);
284:   }
285:}
