60: * does NOT undo it); then DISCARD ALL (= RESET ALL + DEALLOCATE ALL + CLOSE ALL
61: * + UNLISTEN * + DISCARD TEMP/PLANS/SEQUENCES). Returns 0 clean, -1 -> poison. */
62:static int member_reset_real(void *conn)
63:{
64:   char e[256];
65:   /* Only ROLLBACK when a txn is actually open/aborted: an unconditional ROLLBACK
66:    * on an idle connection makes postgres log "no transaction in progress" on
67:    * every pool return (noise). DISCARD ALL below still cannot run inside a txn,
68:    * so any open one must be cleared first. */
69:   if (aimee_pg_in_transaction(conn))
70:      (void)aimee_pg_exec(conn, "ROLLBACK", e, sizeof(e));
71:   if (aimee_pg_exec(conn, "RESET SESSION AUTHORIZATION", e, sizeof(e)) != 0)
72:      return -1;
73:   if (aimee_pg_exec(conn, "DISCARD ALL", e, sizeof(e)) != 0)
74:      return -1;
75:   return 0;
76:}
