292:      g_close(conn);
293:      return;
294:   }
295:   g_close(g_members[i].conn);
296:   g_members[i].conn = NULL;
297:   int64_t now = mono_ms();
298:   char e[256] = "";
299:   if (now - g_members[i].last_reopen >= DB2_POOL_REOPEN_MIN_MS)
300:   {
