227:/* §2b: a Postgres advisory lock serialises fresh-DB dim bootstrap across racing kb
228: * starts. Keyed by hashtext of this string (the mining.c pattern). Bump the _vN
229: * suffix only on a semantics-changing lock change (added waiters / xact-scoped),
230: * never on a code refactor — the value is a wire contract between concurrent kbs. */
231:#define DB2_DIM_LOCK_KEY "aimee_dim_bootstrap_v1"
232:
233:static long db2_mono_ms(void)
234:{
235:   struct timespec ts;
236:   clock_gettime(CLOCK_MONOTONIC, &ts);
237:   return (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
238:}
