287:static void db2_dim_lock_release(void *conn)
288:{
289:   if (aimee_pg_is_shim())
290:      return;
291:   char err[256] = "";
292:   aimee_pg_stmt_t *st =
293:       aimee_pg_prepare(conn, "SELECT pg_advisory_unlock(hashtext(?1))", err, sizeof(err));
294:   if (!st)
295:      return;
296:   aimee_pg_bind_text(st, "?1", DB2_DIM_LOCK_KEY);
297:   (void)aimee_pg_step(st, err, sizeof(err));
298:   aimee_pg_finalize(st);
