520:/* Acquire this thread's connection: a pool lease, or — if the pool is
521: * unavailable/exhausted — a private overflow connection. Stores it in the
522: * thread key so the destructor returns/closes it on thread exit. Caller holds
523: * no lock. Returns NULL if both the pool lease and overflow connection fail;
524: * the caller must fail the operation rather than sharing g_conn. */
525:static void *db2_thread_acquire(void)
526:{
527:   void *conn = NULL;
528:   int pooled = 0;
529:   if (db2_pool_active())
530:   {
531:      conn = db2_pool_lease(0); /* bounded; NULL on exhaustion */
532:      pooled = (conn != NULL);
533:      if (conn && g_lease_site)
534:         db2_pool_note_lease_site(conn, g_lease_site);
535:   }
536:   if (!conn)
537:   {
538:      /* Pool off or exhausted: a private overflow connection keeps the unit of
539:       * work alive (libpq forbids sharing one PGconn across threads). The
540:       * WP-D startup check leaves headroom under max_connections for these. */
541:      char errbuf[256] = "";
542:      conn = aimee_pg_open(g_pg_url[0] ? g_pg_url : NULL, errbuf, sizeof(errbuf));
543:      if (!conn)
544:      {
545:         fprintf(stderr, "aimee: db2_conn: connection acquire failed (%s)\n",
546:                 errbuf[0] ? errbuf : "unknown");
547:         return NULL;
548:      }
549:   }
550:   db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
551:   if (!L)
552:   {
553:      L = (db2_thread_lease_t *)calloc(1, sizeof(*L));
554:      if (!L)
555:      {
556:         if (pooled)
557:            db2_pool_return(conn);
558:         else
559:            aimee_pg_close(conn);
560:         return NULL;
561:      }
562:      if (pthread_setspecific(g_thread_conn_key, L) != 0)
563:      {
564:         free(L);
565:         if (pooled)
566:            db2_pool_return(conn);
567:         else
568:            aimee_pg_close(conn);
569:         return NULL;
570:      }
571:   }
572:   L->conn = conn;
573:   L->pooled = pooled;
574:   return conn;
575:}
