234:/* Find the member index for a leased conn; -1 if not found. Caller holds g_mtx. */
235:static int member_index_locked(void *conn)
236:{
237:   for (int i = 0; i < g_size; i++)
238:      if (g_members[i].conn == conn)
239:         return i;
240:   return -1;
241:}
