276:static void test_starved_pool_gives_up_so_it_can_be_restarted(void)
277:{
278:   install_mock();
279:   char e[128] = "";
280:   assert(db2_pool_init("mock://x", 2, e, sizeof(e)) == 0);
281:   db2_pool_set_test_ceiling_ms(50);
282:   db2_pool_set_test_starved_action(record_starved);
283:   g_starved_calls = 0;
284:   g_starved_reason[0] = '\0';
285:
286:   void *a = db2_pool_lease(1000), *b = db2_pool_lease(1000);
287:   assert(a && b); /* every member leased, and never returned */
288:   usleep(120 * 1000);
289:
290:   pthread_t w;
291:   assert(pthread_create(&w, NULL, starve_waiter, NULL) == 0);
292:   usleep(150 * 1000); /* let the waiter queue */
293:
294:   /* One sweep is not enough: a single unlucky sample must not restart a kb. */
295:   for (int i = 0; i < DB2_POOL_STARVED_SWEEPS - 1; i++)
296:   {
297:      (void)db2_pool_reaper_sweep();
298:      assert(g_starved_calls == 0);
299:   }
300:   (void)db2_pool_reaper_sweep();
301:   assert(g_starved_calls == 1);
302:   assert(strstr(g_starved_reason, "lease leak") != NULL);
303:
304:   pthread_join(w, NULL);
305:   db2_pool_return(a);
306:   db2_pool_return(b);
307:   db2_pool_set_test_starved_action(NULL);
308:   db2_pool_shutdown();
309:}
