488:    *    function. to_regclass/to_regprocedure are catalog lookups any role may run;
489:    *    they return NULL for absent objects (never error). */
490:   static const char *const present_checks[] = {
491:       "SELECT (to_regclass('public.kb_documents') IS NOT NULL)::text",
492:       "SELECT (to_regclass('public.kb_vault_witness_checkpoint') IS NOT NULL)::text",
493:       "SELECT (to_regprocedure('public.org_vault_witness_control_fence()') IS NOT NULL)::text",
494:   };
495:   static const char *const present_names[] = {"kb_documents", "kb_vault_witness_checkpoint",
496:                                               "org_vault_witness_control_fence"};
497:   for (size_t i = 0; i < sizeof present_checks / sizeof present_checks[0]; i++)
498:   {
499:      char e2[256] = "";
500:      aimee_pg_stmt_t *st = aimee_pg_prepare(conn, present_checks[i], e2, sizeof e2);
501:      int present = 0;
502:      if (st && aimee_pg_step(st, e2, sizeof e2) == AIMEE_PG_ROW)
503:      {
504:         const char *v = aimee_pg_column_text(st, 0);
505:         present = (v && v[0] == 't');
506:      }
507:      if (st)
508:         aimee_pg_finalize(st);
509:      if (!present)
510:      {
511:         snprintf(err, errlen,
512:                  "hardened tier: required object %s is absent — schema not migrated or stale",
513:                  present_names[i]);
