608:void db2_lease_end(void)
609:{
610:   if (!g_init_thread_set || pthread_equal(pthread_self(), g_init_thread))
611:      return;
612:   if (g_lease_depth > 0 && --g_lease_depth == 0)
613:   {
614:      db2_thread_lease_t *L = (db2_thread_lease_t *)pthread_getspecific(g_thread_conn_key);
615:      if (L && L->conn)
616:      {
617:         if (L->pooled)
618:            db2_pool_return(L->conn);
619:         else
620:            aimee_pg_close(L->conn);
621:         L->conn = NULL;
622:         L->pooled = 0;
623:      }
624:   }
