243:void db2_pool_return(void *conn)
244:{
245:   if (!conn)
246:      return;
247:   /* Reset OUTSIDE the lock (it does I/O). The member stays marked leased so no
248:    * one else can grab it mid-reset. */
249:   int poisoned = (g_reset(conn) != 0);
250:
251:   pthread_mutex_lock(&g_mtx);
252:   int i = member_index_locked(conn);
253:   if (i < 0)
254:   {
255:      /* Not ours (already replaced by a reaper poison, or stale). Close it. */
256:      pthread_mutex_unlock(&g_mtx);
257:      if (poisoned)
258:         g_close(conn);
259:      return;
260:   }
261:   if (poisoned)
262:   {
263:      int64_t now = mono_ms();
264:      g_close(g_members[i].conn);
265:      g_members[i].conn = NULL;
266:      char e[256] = "";
267:      /* Rate-cap reopen to avoid thrash under a bad-connection storm. */
268:      if (now - g_members[i].last_reopen >= DB2_POOL_REOPEN_MIN_MS)
269:      {
270:         g_members[i].conn = g_open(g_url, e, sizeof(e));
271:         g_members[i].last_reopen = now;
272:      }
273:      g_poisoned++;
274:      if (!g_members[i].conn)
275:         POOL_LOG("member %d poisoned; reopen deferred/failed: %s", i, e);
276:   }
277:   g_members[i].leased = 0;
278:   g_members[i].lease_ms = 0;
279:   pthread_cond_signal(&g_cond);
280:   pthread_mutex_unlock(&g_mtx);
281:}
