314: * lease thread-local destructor (db2_init.c, WP-B) — by the time a thread is
315: * dead its lease has already been returned. A lease still held past the ceiling
316: * therefore means a *live* thread that missed its db2_lease_end(); we CANNOT
317: * safely reclaim it (the thread may still use the connection — libpq forbids
318: * concurrent use), so we log + count it for ops. Returns the number of stuck
319: * leases observed this sweep. */
320:int db2_pool_reaper_sweep(void)
321:{
322:   int stuck = 0, live = 0, waiters = 0;
323:   char reason[256] = "";
324:   pthread_mutex_lock(&g_mtx);
325:   int64_t now = mono_ms();
326:   for (int i = 0; i < g_size; i++)
327:   {
328:      if (!g_members[i].leased || !g_members[i].conn || !g_members[i].lease_ms)
329:         continue;
330:      live++;
331:      if (now - g_members[i].lease_ms > g_hold_ceiling_ms)
332:      {
333:         stuck++;
334:         g_stuck++;
335:         POOL_LOG("member %d leased %lldms (> %lldms ceiling) by %s — missed lease_end?", i,
336:                  (long long)(now - g_members[i].lease_ms), (long long)g_hold_ceiling_ms,
337:                  g_members[i].site ? g_members[i].site : "unattributed");
338:      }
339:   }
340:   waiters = g_waiters;
341:
342:   /* SELF-HEAL. Every member stuck past the ceiling, with callers queued behind
343:    * them, is not slowness — it is a lease leak, and this pool deliberately
344:    * cannot reclaim (a live thread may still be using the connection; libpq
345:    * forbids concurrent use). So no future sweep can improve matters: the
346:    * process will serve nothing from here until it is restarted.
347:    *
348:    * Measured: a kb in exactly this state logged 1096 consecutive failed health
349:    * checks over ~3 hours with every pool member held ~4.5 hours past a 5-minute
350:    * ceiling, and sat there. /v1/health is a static string and still timed out,
351:    * because no worker thread was free to answer it — a starved pool starves the
352:    * whole HTTP surface, so nothing outside the process can even see why.
353:    *
354:    * Requires waiters: a fully-leased pool with nobody queued is a busy kb, not
355:    * a stuck one. Requires several consecutive sweeps so one unlucky sample
356:    * cannot restart a healthy service. */
357:   int starved = (g_size > 0 && stuck == g_size && stuck == live && waiters > 0);
358:   if (starved)
359:   {
360:      g_starved_sweeps++;
361:      snprintf(reason, sizeof(reason),
362:               "all %d pool members stuck past the %lldms ceiling with %d waiter(s) for %d "
363:               "consecutive sweeps — lease leak, unrecoverable in-process",
364:               g_size, (long long)g_hold_ceiling_ms, waiters, g_starved_sweeps);
365:   }
366:   else
367:      g_starved_sweeps = 0;
368:   int give_up = starved && g_starved_sweeps >= DB2_POOL_STARVED_SWEEPS;
369:   void (*action)(const char *) = g_starved_action;
370:   pthread_mutex_unlock(&g_mtx);
371:
372:   if (give_up)
373:   {
374:      POOL_LOG("FATAL: %s; exiting so the restart policy can recover", reason);
375:      if (action)
376:         action(reason);
377:      else
378:      {
379:         /* _exit, not abort: this is a diagnosed unrecoverable state, not memory
380:          * corruption, and a core dump of a pool full of idle connections tells
381:          * an operator nothing the log line above does not. */
382:         fflush(NULL);
383:         _exit(DB2_POOL_STARVED_EXIT_CODE);
384:      }
385:   }
386:   return stuck;
387:}
