416:int db1_work_item_set_terminal(const char *wi, const char *state)
417:{
418:   sqlite3 *db = db1_conn();
419:   if (!db || !wi)
420:      return -1;
421:   static const char *sql =
422:       "UPDATE lifecycle_work_item SET state=?, pause_reason='', paused_state='', "
423:       "updated_at=datetime('now') WHERE work_item_id=?";
424:   sqlite3_stmt *st = NULL;
425:   if (sqlite3_prepare_v2(db, sql, -1, &st, NULL) != SQLITE_OK)
426:      return -1;
427:   sqlite3_bind_text(st, 1, state ? state : "accepted", -1, SQLITE_TRANSIENT);
428:   sqlite3_bind_text(st, 2, wi, -1, SQLITE_TRANSIENT);
429:   int rc = sqlite3_step(st);
430:   sqlite3_finalize(st);
431:   return rc == SQLITE_DONE ? 0 : -1;
432:}
