434:int db1_work_item_abandon_children(const char *parent_id)
435:{
436:   sqlite3 *db = db1_conn();
437:   if (!db || !parent_id || !parent_id[0])
438:      return -1;
439:   /* Terminating a parent build run must terminate its foreach.workflow child
440:    * slices too: an orphaned non-terminal child keeps being scheduled and
441:    * re-dispatches delegates forever (observed live — an abandoned parent whose
442:    * `.s0` slice looped to no end, leaking a container per round). Mark every
443:    * child not already terminal as 'abandoned'. Slices are leaf runs, so one
444:    * level suffices. */
445:   static const char *sql =
446:       "UPDATE lifecycle_work_item SET state='abandoned', pause_reason='', paused_state='', "
447:       "updated_at=datetime('now') "
448:       "WHERE parent_id=? AND state NOT IN ('accepted','rejected','abandoned')";
449:   sqlite3_stmt *st = NULL;
450:   if (sqlite3_prepare_v2(db, sql, -1, &st, NULL) != SQLITE_OK)
451:      return -1;
