348:int db1_work_item_submit_capped(const char *work_item_id, const char *repo,
349:                                const char *proposal_path, const char *workflow_name,
350:                                const char *workflow_version, const char *start_stage,
351:                                const char *submitter, int max_active, int rate_max, int rate_secs)
352:{
353:   if (!work_item_id || !work_item_id[0] || !submitter || !submitter[0])
354:      return -1;
355:   /* One BEGIN IMMEDIATE around cap-check + create + submitter-bind + audit so
356:    * concurrent submits from one principal serialize (the second blocks on the
357:    * write lock, then its COUNT sees the first's row) — the cap can't be exceeded
358:    * by the request-burst factor. Every step is fail-CLOSED: a -1 from a count
359:    * (DB fault) or any failed write rolls back, so a partial/uncapped/unattributed
360:    * run never escapes. Returns 0=created, 1=concurrency cap, 2=rate cap, -1=error. */
361:   if (db1_lifecycle_txn_begin() != 0)
362:      return -1;
363:   int active = db1_work_item_count_active_by_submitter(submitter);
364:   if (active < 0)
365:   {
366:      db1_lifecycle_txn_rollback();
367:      return -1;
368:   }
369:   if (max_active > 0 && active >= max_active)
370:   {
371:      db1_lifecycle_txn_rollback();
372:      return 1;
373:   }
374:   if (rate_max > 0 && rate_secs > 0)
375:   {
376:      int recent = db1_work_item_count_recent_by_submitter(submitter, rate_secs);
377:      if (recent < 0)
378:      {
379:         db1_lifecycle_txn_rollback();
380:         return -1;
381:      }
382:      if (recent >= rate_max)
383:      {
384:         db1_lifecycle_txn_rollback();
385:         return 2;
386:      }
387:   }
388:   const char *start = start_stage ? start_stage : "intake";
389:   if (db1_work_item_create(work_item_id, repo, proposal_path, workflow_name, workflow_version,
390:                            start, "autonomous") != 0 ||
391:       db1_work_item_set_submitter(work_item_id, submitter) != 0)
392:   {
393:      db1_lifecycle_txn_rollback();
394:      return -1;
395:   }
396:   /* Parity "create" event (matches the interactive wfe_work_item_create path) plus
397:    * the attributed, self-locating "submit" audit row (repo + proposal + id). */
398:   char detail[512];
399:   snprintf(detail, sizeof detail, "submit repo=%s proposal=%s id=%s", repo ? repo : "",
400:            proposal_path ? proposal_path : "", work_item_id);
401:   if (db1_lifecycle_event_add(work_item_id, start, "create", submitter,
402:                               workflow_name ? workflow_name : "", workflow_version, 0) != 0 ||
403:       db1_lifecycle_event_add(work_item_id, start, "submit", submitter, detail, "", 0) != 0)
404:   {
405:      db1_lifecycle_txn_rollback();
406:      return -1;
407:   }
408:   if (db1_lifecycle_txn_commit() != 0)
409:   {
410:      db1_lifecycle_txn_rollback();
411:      return -1;
412:   }
413:   return 0;
414:}
