51:/* Size the frame from the arguments themselves.
52:
53:   These carry prompts, results and JSON documents, not just identifiers, and
54:   in-process callers have always passed them whole. A fixed cap here would
55:   refuse exactly those calls and return the same -1 as a broken store -- fine
56:   in a test with short strings, wrong the first time a real prompt arrives. The
57:   bus bounds the message instead. */
58:static int frame_size(const char *const *fields, uint32_t count, size_t *need_out)
59:{
60:   /* Zero fields is a legal request: an operation that takes no arguments
61:      sends the header alone. The upper bound still applies. */
62:   if (count > AIMEE_DB1_FIELDS_MAX)
63:      return -1;
64:   size_t need = 8u;
65:   for (uint32_t i = 0; i < count; ++i)
66:   {
67:      /* Empty is legal on the wire: an optional field the caller left out
68:         travels as zero length. Which fields may be empty is the operation's
69:         business, checked before the frame is built. */
70:      if (!fields[i])
71:         return -1;
72:      size_t n = strlen(fields[i]);
73:      if (n > AIMEE_MODULE_MESSAGE_MAX_BODY - need - 4u)
74:         return -1;
75:      need += 4u + n;
76:   }
77:   *need_out = need;
78:   return 0;
79:}
