81:/* op(u32) | field_count(u32) | (len(u32) | bytes) * count, per db1_module_api.h. */
82:static void encode(uint8_t *out, uint32_t op, const char *const *fields, uint32_t count)
83:{
84:   uint32_t at = 0;
85:   aimee_db1_put_u32(out + at, op);
86:   at += 4u;
87:   aimee_db1_put_u32(out + at, count);
88:   at += 4u;
89:   for (uint32_t i = 0; i < count; ++i)
90:   {
91:      uint32_t n = (uint32_t)strlen(fields[i]);
92:      aimee_db1_put_u32(out + at, n);
93:      at += 4u;
94:      memcpy(out + at, fields[i], n);
95:      at += n;
96:   }
97:}
