99:/* Returns the module's status, or -1 when the call never produced one. */
100:/* Fills up to `slots` reply values, each into the buffer and capacity the
101:   caller supplied. A write passes none; a read passes one; a row passes one per
102:   member; a list passes one per member per row it is willing to accept.
103:
104:   `filled_out` reports how many values the reply actually carried, which is how
105:   a list learns its length: the rows are not counted separately on the wire
106:   because an operation already knows how wide its rows are. Callers that expect
107:   a fixed shape pass NULL. */
108:static int call_stage(uint32_t op, const char *const *fields, uint32_t count, char *const *values,
109:                      const size_t *caps, uint32_t slots, uint32_t *filled_out)
110:{
111:   if (filled_out)
112:      *filled_out = 0u;
113:   for (uint32_t i = 0; i < slots; ++i)
114:      if (values[i] && caps[i])
115:         values[i][0] = '\0';
116:   /* A local check, not a probe: with nothing serving the stage there is no
117:      call to make, and saying so beats waiting out a deadline. */
118:   if (!obs_bus_module_available(AIMEE_DB1_EVENT_LIFECYCLE))
119:   {
120:      warn_unreachable(AIMEE_MODULE_CALL_CAPABILITY_ABSENT);
121:      return -1;
122:   }
123:
124:   size_t request_len = 0;
125:   if (frame_size(fields, count, &request_len) != 0)
126:      return -1;
127:   /* The reply is bounded by the caller's own buffer: it asked for at most
128:      value_len bytes, so there is no reason to hold more than that. */
129:   size_t response_cap = 8u;
130:   for (uint32_t i = 0; i < slots; ++i)
131:      response_cap += 4u + caps[i];
132:   uint8_t *request = malloc(request_len);
133:   uint8_t *response = malloc(response_cap);
134:   if (!request || !response)
135:   {
136:      free(request);
137:      free(response);
138:      return -1;
139:   }
140:   encode(request, op, fields, count);
141:
142:   uint32_t response_len = 0;
143:   uint64_t deadline = aimee_module_call_deadline_ns(DB1_LIFECYCLE_CALL_TIMEOUT_MS);
144:   aimee_module_call_result_t rc =
145:       obs_bus_module_call(AIMEE_DB1_EVENT_LIFECYCLE, AIMEE_DB1_STAGE_LIFECYCLE, 0, deadline,
146:                           request, (uint32_t)request_len, response, (uint32_t)response_cap,
147:                           &response_len, NULL, NULL);
148:   free(request);
149:
150:   int result = -1;
151:   if (rc != AIMEE_MODULE_CALL_OK || response_len < 8u)
152:      warn_unreachable((int)rc);
153:   else
154:   {
155:      uint32_t status = aimee_db1_get_u32(response);
156:      uint32_t fields_in = aimee_db1_get_u32(response + 4u);
157:      /* Read the reply's own count rather than assuming an arity: a status with
158:         no values is how a write answers, one value is a read, and a member
159:         apiece is a row. */
160:      result = (int)status;
161:      /* More values than the caller has room for is a contract mismatch, not
162:         something to read the first few of: the caller asked for at most this
163:         many rows, and a stage answering with more is not answering this call. */
164:      if (fields_in > slots)
165:         result = -1;
166:      else if (filled_out)
167:         *filled_out = fields_in;
168:      /* Fewer values than the caller has slots for is the same contract
169:         mismatch read from the other side, and it used to pass: the unfilled
170:         slots keep the empty string cleared above, so the caller reads a row
171:         whose last members are blank and cannot tell that from a row that is
172:         blank. A list says how many rows it found through filled_out and is
173:         variable by construction; every other shape has one arity, and a stage
174:         answering with a different one is a stage built against a different
175:         version of this contract. Two processes, two binaries, two deployment
176:         times -- so say it rather than zero-fill. */
177:      else if (status == (uint32_t)AIMEE_DB1_STATUS_OK && fields_in != slots)
178:         result = -1;
179:      uint32_t at = 8u;
180:      for (uint32_t i = 0; i < fields_in && result != -1; ++i)
181:      {
182:         if (at + 4u > response_len)
183:         {
184:            result = -1;
185:            break;
186:         }
187:         uint32_t n = aimee_db1_get_u32(response + at);
188:         at += 4u;
189:         /* A reply whose declared length runs past what arrived is not a reply
190:            to read part of. */
191:         if (at + n > response_len)
192:         {
193:            result = -1;
194:            break;
195:         }
196:         if (i < slots && values[i] && caps[i])
197:         {
198:            /* No room for the terminator is no room: writing it would land one
199:               byte past the buffer the caller owns. */
200:            if (n >= caps[i])
201:               result = -1;
202:            else
203:            {
204:               memcpy(values[i], response + at, n);
205:               values[i][n] = '\0';
206:            }
207:         }
208:         at += n;
209:      }
210:   }
211:   free(response);
212:   return result;
213:}
