591:         clone_url_norm = util_url_normalize(url);
592:         clone_url = clone_url_norm ? clone_url_norm : url;
593:      }
594:      /* Destination pinned by fd: the child chdirs to /proc/self/fd/<tmpfd>
595:       * (pre-exec, while the fd is still open) and clones into ".", so git
596:       * never resolves an attacker-influencable path string. */
