624:      struct stat hst;
625:      if (rc != 0 || fstatat(tmpfd, ".git/HEAD", &hst, 0) != 0)
626:      {
627:         /* Publish is conditional on git exit 0 AND a present .git/HEAD — a
628:          * partially-initialized repo never publishes. */
