75:/* Sanitize a candidate org component to the ws_scope_name_valid alphabet:
76: * invalid bytes -> '-', runs collapsed, leading/trailing '-'/'.' trimmed.
77: * Returns 0 iff the FULL sanitized result fits WS_REF_COMP_MAX and passes
78: * ws_scope_name_valid — an over-long org is REJECTED, never truncated (two
79: * distinct overrides must never collapse onto one identity). */
80:static int sanitize_org(const char *in, char *out, size_t cap)
81:{
82:   if (!in || !in[0] || cap == 0)
83:      return -1;
84:   size_t o = 0;
85:   int last_dash = 0;
86:   for (const char *p = in; *p; p++)
87:   {
88:      unsigned char c = (unsigned char)*p;
89:      int ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ||
90:               c == '.' || c == '_';
91:      if (ok)
92:      {
93:         if (o >= WS_REF_COMP_MAX || o + 1 >= cap)
94:            return -1; /* sanitized form overflows the component cap */
95:         out[o++] = (char)c;
96:         last_dash = 0;
97:      }
98:      else if (!last_dash && o > 0) /* collapse runs; no leading '-' */
99:      {
100:         if (o >= WS_REF_COMP_MAX || o + 1 >= cap)
101:            return -1;
102:         out[o++] = '-';
103:         last_dash = 1;
104:      }
105:   }
106:   while (o > 0 && (out[o - 1] == '-' || out[o - 1] == '.'))
107:      o--;
108:   out[o] = '\0';
109:   return (o > 0 && ws_scope_name_valid(out)) ? 0 : -1;
110:}
