163:int git_project_derive_org(const char *url, char *out, size_t cap, int *multi_segment)
164:{
165:   if (multi_segment)
166:      *multi_segment = 0;
167:   if (!url || !out || cap == 0)
168:      return -1;
169:   out[0] = '\0';
170:   char remote[GP_PATH_MAX];
171:   if (git_project_canonical_remote(url, remote, sizeof(remote)) != 0)
172:      return -1;
173:   const char *scheme_end = strstr(remote, "://");
174:   if (!scheme_end)
175:      return -1; /* local path etc. — no derivable owner */
176:   const char *path = strchr(scheme_end + 3, '/');
177:   if (!path)
178:      return -1;
179:   path++; /* first owner segment */
180:   const char *last_slash = strrchr(path, '/');
181:   if (!last_slash || last_slash == path)
182:      return -1; /* no owner segment at all: https://host/repo */
183:   /* owner path = [path, last_slash); multi-segment (subgroups) bails out —
184:    * a joined org is lossy; the caller may pass an explicit override. */
185:   char owner[GP_PATH_MAX];
186:   size_t ol = (size_t)(last_slash - path);
187:   if (ol >= sizeof(owner))
188:      return -1;
189:   memcpy(owner, path, ol);
190:   owner[ol] = '\0';
191:   if (strchr(owner, '/'))
192:   {
193:      if (multi_segment)
194:         *multi_segment = 1;
195:      return -1;
196:   }
197:   return sanitize_org(owner, out, cap) == 0 ? 0 : -1;
198:}
