131:/* Zero `n` bytes of `p` so the wipe can't be optimised away. */
132:static void wipe(void *p, size_t n)
133:{
134:   volatile unsigned char *v = (volatile unsigned char *)p;
135:   while (n--)
136:      *v++ = 0;
137:}
