90:/* POST /v1/workspace/clone {url, name?} — clone a repo as a project under the
91: * calling webchat user's scoped workspace (webchat-git WP-D). The caller
92: * principal comes from the attested identity (root-UDS-gated X-Aimee-Webuser),
93: * NOT the body — a user can only clone into their own tree. Credentials are
94: * injected from the user's sealed vault (WP-C); never accepted in the body. */
95:int rh_workspace_clone(const route_req_t *rq, char *resp, int cap)
96:{
97:   if (!git_surface_enabled())
98:      return err_json(resp, cap, 503, "the git surface is disabled on this server");
99:   const char *principal = server_http_identity_principal();
100:   if (!principal || strncmp(principal, "webuser:", 8) != 0)
101:      return err_json(resp, cap, 403, "git projects require a webchat user");
102:
103:   cJSON *body = (rq->body && rq->body[0]) ? cJSON_Parse(rq->body) : NULL;
104:   if (!body || !cJSON_IsObject(body))
105:   {
106:      cJSON_Delete(body);
107:      return err_json(resp, cap, 400, "invalid JSON body");
108:   }
109:   const cJSON *jurl = cJSON_GetObjectItemCaseSensitive(body, "url");
110:   const cJSON *jname = cJSON_GetObjectItemCaseSensitive(body, "name");
111:   const cJSON *jorg = cJSON_GetObjectItemCaseSensitive(body, "org");
112:   const cJSON *jtoken = cJSON_GetObjectItemCaseSensitive(body, "token");
113:   const char *url = (cJSON_IsString(jurl) && jurl->valuestring) ? jurl->valuestring : NULL;
114:   const char *name = (cJSON_IsString(jname) && jname->valuestring) ? jname->valuestring : NULL;
115:   /* An empty-string org (the webchat relay always sends the field) means
116:    * "derive", identical to an absent field. */
117:   const char *org = (cJSON_IsString(jorg) && jorg->valuestring[0]) ? jorg->valuestring : NULL;
118:   const char *token = (cJSON_IsString(jtoken) && jtoken->valuestring) ? jtoken->valuestring : NULL;
119:
120:   if (!util_url_is_remote(url))
121:   {
122:      cJSON_Delete(body);
123:      return err_json(resp, cap, 400, "clone url must be an http(s), ssh, or git remote");
124:   }
125:
126:   char dest[MAX_PATH_LEN], pname[GIT_PROJECT_NAME_MAX], err[256];
127:   int rc = git_project_clone(principal, url, name, org, token, dest, sizeof(dest), pname,
128:                              sizeof(pname), err, sizeof(err));
129:   /* A multi-segment owner (GitLab subgroups) bails to a flat clone by design;
130:    * tell the caller how to place it under an org explicitly. (Checked before
131:    * body teardown — url points into it.) */
132:   int flat_multi = 0;
133:   if (rc == 0 && !org)
134:   {
135:      int multi = 0;
136:      char cand[65];
137:      if (git_project_derive_org(url, cand, sizeof(cand), &multi) != 0 && multi)
138:         flat_multi = 1;
139:   }
140:   char org_cands[256] = "";
141:   if (flat_multi)
142:      (void)git_project_org_candidates(url, org_cands, sizeof(org_cands));
143:   cJSON_Delete(body);
144:   if (rc != 0)
145:      /* Identity conflicts (existing project, flat/org clash, same key bound
146:       * to a different remote) are 409; validation failures stay 400. */
147:      return err_json(resp, cap, rc == GP_ERR_CONFLICT ? 409 : 400, err);
148:
149:   /* Best-effort index so the new project is searchable by the agent + listed. */
150:   index_scan_project(pname, dest, 0);
151:
152:   cJSON *out = cJSON_CreateObject();
153:   cJSON_AddBoolToObject(out, "ok", 1);
154:   cJSON_AddStringToObject(out, "name", pname); /* the project REF (org/repo or flat) */
155:   if (flat_multi)
156:   {
157:      char note[512];
158:      snprintf(note, sizeof(note),
159:               "multi-segment owner path (candidate orgs: %s): cloned flat; pass an explicit "
160:               "'org' to place it under an org",
161:               org_cands[0] ? org_cands : "none derivable");
162:      cJSON_AddStringToObject(out, "org_note", note);
163:   }
164:   rh_clone_kb_scan(pname, dest, out);
165:   char *s = cJSON_PrintUnformatted(out);
166:   int n = s ? snprintf(resp, (size_t)cap, "%s", s) : -1;
167:   free(s);
168:   cJSON_Delete(out);
169:   return (n > 0 && n < cap) ? 200 : err_json(resp, cap, 500, "response too large");
170:}
