140: * Returns 1 (token written) or 0 (none — caller may still have ssh/ambient).
141: * `out` is always either a full token or empty; never a partial value. */
142:static int resolve_token(const char *principal, const char *remote_url, const char *repo_dir,
143:                         const char *preferred_token, char *out, size_t cap)
144:{
145:   if (out && cap)
146:      out[0] = '\0';
147:   if (!out || cap == 0)
148:      return 0;
149:
150:   /* 1. A live caller-supplied token (inline clone token / workspace broker). */
151:   if (preferred_token && preferred_token[0])
152:   {
153:      if ((size_t)snprintf(out, cap, "%s", preferred_token) < cap)
154:         return 1;
155:      wipe(out, cap); /* would truncate a secret → wipe the partial, fail closed */
156:      return 0;
157:   }
158:
159:   /* 2. Per-host vault token, keyed by the repo's remote host (resolved from the
160:    * explicit remote URL, else the checkout's `origin`), via the shared seam. */
161:   if (git_host_resolve_token(remote_url, repo_dir, out, cap) == 1 && out[0])
162:      return 1;
163:   out[0] = '\0';
164:
165:   /* 3. The principal's own vaulted personal forge token. */
166:   if (principal && principal[0] && git_forge_vault_token(principal, out, cap) == 1 && out[0])
167:      return 1;
168:   out[0] = '\0';
169:
170:   /* 4. The server's own git identity (App installation token / AIMEE_FORGE_TOKEN). */
171:   if (forge_cred_server_identity(out, cap, NULL, 0) == 1 && out[0])
172:      return 1;
173:   out[0] = '\0';
174:   return 0;
175:}
