335:   if (!principal || strncmp(principal, "webuser:", 8) != 0)
336:   {
337:      snprintf(err, errlen, "git projects require a webchat user");
338:      return -1;
339:   }
340:   if (!ws_scope_openat2_available())
341:   {
342:      snprintf(err, errlen,
343:               "the webuser project surface requires openat2 (Linux >= 5.6); it is disabled on "
344:               "this kernel");
345:      return -1;
346:   }
347:   if (!ws_reg_ready())
348:   {
349:      snprintf(err, errlen, "the project registry is unavailable; try again shortly");
350:      return -1;
351:   }
352:   /* Reject an empty or flag-like URL. The '--' separator below also stops git
353:    * from treating the URL as an option, but reject the obvious case early. */
354:   if (!url || !url[0] || url[0] == '-')
355:   {
356:      snprintf(err, errlen, "invalid repository URL");
357:      return -1;
358:   }
359:   /* No control chars / whitespace in the URL (defensive; argv already avoids a
360:    * shell, but keep the value clean for logs and git). */
361:   for (const char *p = url; *p; p++)
362:      if ((unsigned char)*p < 0x20 || *p == ' ')
363:      {
364:         snprintf(err, errlen, "invalid repository URL");
365:         return -1;
366:      }
367:
368:   char repo[WS_REF_COMP_MAX + 1];
369:   if (derive_name(url, name, repo, sizeof(repo)) != 0)
370:   {
371:      snprintf(err, errlen, "could not derive a valid project name");
372:      return -1;
373:   }
374:
375:   /* Org: explicit override wins; else derived ONCE from the URL owner path
376:    * (multi-segment owners bail to flat); else flat fallback. The single
377:    * sanitized value is used for the conflict checks, the registry, the
378:    * layout, and the ref — nothing re-derives it. */
379:   char org[WS_REF_COMP_MAX + 1] = "";
380:   if (org_in && org_in[0])
381:   {
382:      if (sanitize_org(org_in, org, sizeof(org)) != 0)
383:      {
384:         snprintf(err, errlen, "invalid org override");
385:         return -1;
386:      }
387:   }
388:   else
389:      (void)git_project_derive_org(url, org, sizeof(org), NULL); /* flat on failure */
390:
391:   char ref[WS_REF_MAX + 1];
392:   if (org[0])
393:      snprintf(ref, sizeof(ref), "%s/%s", org, repo);
394:   else
395:      snprintf(ref, sizeof(ref), "%s", repo);
396:
397:   char remote[GP_PATH_MAX];
398:   if (git_project_canonical_remote(url, remote, sizeof(remote)) != 0)
399:   {
400:      snprintf(err, errlen, "could not derive a canonical remote from the URL");
401:      return -1;
402:   }
403:
404:   /* ---- lifecycle-locked section: conflict checks -> register -> create ----
405:    * The first-component lock serializes flat/org namespace conflicts,
406:    * registration, publication, deletion, and org pruning deployment-wide. */
407:   int lockfd = ws_reg_lock(ref);
408:   if (lockfd < 0)
409:   {
410:      snprintf(err, errlen, "could not acquire the project lifecycle lock");
411:      return -1;
412:   }
413:   int registered = 0, rootfd = -1, orgfd = -1, tmpfd = -1, destfd_parent = -1;
414:   char tmpname[WS_REF_COMP_MAX + 32];
415:   tmpname[0] = '\0';
416:   int rc_final = -1;
417:
418:   rootfd = ws_scope_open_user_root(principal);
419:   if (rootfd < 0)
420:   {
421:      snprintf(err, errlen, "could not open the workspace root");
422:      goto out;
423:   }
424:
425:   /* Caller's own tree: the target must not exist (as anything). */
426:   {
427:      struct stat st;
428:      const char *probe = org[0] ? org : repo;
429:      if (org[0])
430:      {
431:         int ofd = ws_scope_openat2_dir(rootfd, org);
432:         if (ofd >= 0)
433:         {
434:            int exists = fstatat(ofd, repo, &st, AT_SYMLINK_NOFOLLOW) == 0;
435:            close(ofd);
436:            if (exists)
437:            {
438:               rc_final = GP_ERR_CONFLICT;
439:               snprintf(err, errlen, "project '%s' already exists", ref);
440:               goto out;
441:            }
442:         }
443:         /* flat/org namespace conflict: org name taken by a flat project */
444:         if (is_published_project_at(rootfd, org))
445:         {
446:            rc_final = GP_ERR_CONFLICT;
447:            snprintf(err, errlen, "a project named '%s' already exists; the org name is taken",
448:                     org);
449:            goto out;
450:         }
451:      }
452:      else
453:      {
454:         if (fstatat(rootfd, probe, &st, AT_SYMLINK_NOFOLLOW) == 0)
455:         {
456:            /* flat target exists — as a project (409) or as an org dir (the
457:             * reverse namespace conflict). */
458:            rc_final = GP_ERR_CONFLICT;
459:            if (is_published_project_at(rootfd, probe))
460:               snprintf(err, errlen, "project '%s' already exists", ref);
461:            else
462:               snprintf(err, errlen, "an org named '%s' already exists; pass an explicit org",
463:                        repo);
464:            goto out;
465:         }
466:      }
467:   }
468:
469:   /* Registry: same key bound to a different remote anywhere -> generic 409
470:    * (no cross-principal disclosure: neither the other remote nor its holder
471:    * is echoed). */
472:   {
473:      char cur_remote[GP_PATH_MAX];
474:      int holders = 0;
475:      int found = ws_reg_lookup(ref, cur_remote, sizeof(cur_remote), &holders);
476:      if (found < 0)
477:      {
478:         snprintf(err, errlen, "project registry unavailable");
479:         goto out;
480:      }
481:      if (found == 1)
482:      {
483:         /* The registry entry may be stale after a holder's `git remote
484:          * set-url` — in EITHER direction: a stale mismatch would spuriously
485:          * 409 a legitimate clone, and a stale MATCH would silently join a
486:          * ref whose holders have since diverged. Resync this ref from the
487:          * holders' git configs (authoritative, under the held lock) before
488:          * any comparison or increment. */
489:         if (ws_reg_resync(ref) != 0 ||
490:             (found = ws_reg_lookup(ref, cur_remote, sizeof(cur_remote), &holders)) < 0)
491:         {
492:            snprintf(err, errlen, "project registry unavailable");
493:            goto out;
494:         }
495:         if (found == 1 && strcmp(cur_remote, remote) != 0)
496:         {
497:            rc_final = GP_ERR_CONFLICT;
498:            snprintf(err, errlen,
499:                     "ref '%s' is already bound to a different remote; pass a distinct org", ref);
500:            goto out;
501:         }
502:      }
503:   }
504:   {
505:      int reg_rc = ws_reg_register(ref, remote);
506:      if (reg_rc == 1)
507:      {
508:         rc_final = GP_ERR_CONFLICT;
509:         snprintf(err, errlen,
510:                  "ref '%s' is already bound to a different remote; pass a distinct org", ref);
511:         goto out;
512:      }
513:      if (reg_rc != 0)
514:      {
515:         snprintf(err, errlen, "could not register the project key");
516:         goto out;
517:      }
518:   }
519:   registered = 1;
520:
521:   /* Create: org dir (mkdirat + openat2 re-open), temp clone dir, clone with
522:    * the destination pinned by fd, sidecar, then atomic rename-publish. */
523:   if (org[0])
524:   {
525:      if (mkdirat(rootfd, org, 0700) != 0 && errno != EEXIST)
526:      {
527:         snprintf(err, errlen, "could not create the org directory");
528:         goto out;
529:      }
530:      orgfd = ws_scope_openat2_dir(rootfd, org);
531:      if (orgfd < 0)
532:      {
533:         snprintf(err, errlen, "could not open the org directory");
534:         goto out;
535:      }
536:      struct stat ost;
537:      if (fstat(orgfd, &ost) != 0 || !S_ISDIR(ost.st_mode) || ost.st_uid != geteuid())
538:      {
539:         snprintf(err, errlen, "org directory failed the ownership check");
540:         goto out;
541:      }
542:   }
543:   destfd_parent = org[0] ? orgfd : rootfd;
544:   snprintf(tmpname, sizeof(tmpname), ".tmp-%s-%d", repo, (int)getpid());
545:   /* Stale leftover from a crashed clone only: the cleanup targets this exact
546:    * ".tmp-<repo>-<pid>" name and never touches ".deleting-*" markers — those
547:    * belong to the delete path's resumable tombstones. */
548:   (void)rm_rf_at(destfd_parent, tmpname);
549:   if (mkdirat(destfd_parent, tmpname, 0700) != 0)
550:   {
551:      snprintf(err, errlen, "could not create the clone staging directory");
552:      tmpname[0] = '\0';
553:      goto out;
554:   }
555:   tmpfd = ws_scope_openat2_dir(destfd_parent, tmpname);
556:   if (tmpfd < 0)
557:   {
558:      snprintf(err, errlen, "could not open the clone staging directory");
559:      goto out;
560:   }
