10:#include "cJSON.h"           /* kb purge reply parsing (delete path) */
11:#include "config.h"          /* kb_purge_fence_ttl_s (heartbeat cadence) */
12:#include "git_cred_inject.h" /* git_cred_inject_build_env_for_repo / _free_env */
13:#include "git_host_cred.h"   /* per-host token store (single-user, many hosts) */
