36:/* Derive a valid single-component repo name from `name_in` (if non-empty) or
37: * the basename of `url` (stripping a trailing ".git" and any trailing '/').
38: * Returns 0 + out, or -1 if no valid name can be formed. */
39:static int derive_name(const char *url, const char *name_in, char *out, size_t cap)
40:{
41:   if (name_in && name_in[0])
42:   {
43:      if (!ws_scope_name_valid(name_in) || strlen(name_in) >= cap)
44:         return -1;
45:      snprintf(out, cap, "%s", name_in);
46:      return 0;
47:   }
48:   if (!url || !url[0])
49:      return -1;
50:   /* basename: last segment after '/' or ':'. */
51:   const char *base = url + strlen(url);
52:   while (base > url && base[-1] == '/') /* ignore trailing slashes */
53:      base--;
54:   const char *end = base;
55:   while (base > url && base[-1] != '/' && base[-1] != ':')
56:      base--;
57:   size_t len = (size_t)(end - base);
58:   if (len == 0 || len >= cap)
59:      return -1;
60:   char tmp[256];
61:   if (len >= sizeof(tmp))
62:      return -1;
63:   memcpy(tmp, base, len);
64:   tmp[len] = '\0';
65:   /* strip a trailing ".git". */
66:   size_t tl = strlen(tmp);
67:   if (tl > 4 && strcmp(tmp + tl - 4, ".git") == 0)
68:      tmp[tl - 4] = '\0';
69:   if (!ws_scope_name_valid(tmp) || strlen(tmp) >= cap)
70:      return -1;
71:   snprintf(out, cap, "%s", tmp);
72:   return 0;
73:}
