126:int git_project_canonical_remote(const char *url, char *out, size_t cap)
127:{
128:   if (!url || !url[0] || !out || cap == 0)
129:      return -1;
130:   char *norm = util_url_normalize(url);
131:   const char *u = norm ? norm : url;
132:   /* Strip userinfo: scheme://user:pass@host/... -> scheme://host/... — the
133:    * canonical remote is CREDENTIAL-FREE by contract; it is stored in sidecars
134:    * and echoed in responses/logs. */
135:   const char *scheme_end = strstr(u, "://");
136:   char buf[GP_PATH_MAX];
137:   if (scheme_end)
