301:/* Does `name` under `dirfd` exist as a dir containing a .git entry (i.e. a
302: * published flat project)? 0/1. */
303:static int is_published_project_at(int dirfd, const char *name)
304:{
305:   int fd = openat(dirfd, name, O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
306:   if (fd < 0)
307:      return 0;
