63:       * doesn't inherit the engine's blocked signals (e.g. SIGCHLD/SIGPIPE). */
64:      sigset_t empty;
65:      sigemptyset(&empty);
66:      sigprocmask(SIG_SETMASK, &empty, NULL);
67:      /* redirect stdout/stderr to pipe, close stdin */
68:      close(pipefd[0]);
69:      dup2(pipefd[1], STDOUT_FILENO);
70:      dup2(pipefd[1], STDERR_FILENO);
71:      close(pipefd[1]);
72:      /* Inherit one specific fd (e.g. a memfd holding a credential the askpass
73:       * reads) at a fixed number for the exec'd command, cleared of CLOEXEC. The
74:       * source fd is CLOEXEC in the parent, so a concurrent exec in another
75:       * thread can never leak it — only this child receives it, and only at
76:       * target_fd. */
77:      if (inherit_fd >= 0 && target_fd >= 0)
78:      {
79:         if (inherit_fd != target_fd)
80:         {
81:            if (dup2(inherit_fd, target_fd) < 0) /* dup2 clears CLOEXEC on target_fd */
82:               _exit(127);
83:         }
84:         else if (fcntl(target_fd, F_SETFD, 0) < 0)
85:         {
86:            _exit(127);
87:         }
88:      }
89:      /* Pin the working directory before exec so the command runs in the caller's
90:       * chosen dir (e.g. the work-item repo), not the engine's inherited cwd. A
91:       * failed chdir must NOT silently fall back to the parent cwd. */
92:      if (cwd && cwd[0] && chdir(cwd) != 0)
93:         _exit(127);
