192:         if (w < 0)
193:            /* Can't determine the child's status (e.g. ECHILD — externally
194:             * reaped): report failure rather than a false success. */
195:            return -1;
196:         if (now_ms() >= deadline)
197:         {
198:            kill(pid, SIGKILL);
199:            reap_bounded(pid, 2000);
200:            return SAFE_EXEC_TIMEOUT;
201:         }
202:         struct timespec ts = {.tv_sec = 0, .tv_nsec = 10 * 1000000}; /* 10ms */
203:         nanosleep(&ts, NULL);
204:      }
205:   }
206:   else
207:   {
208:      waitpid(pid, &status, 0);
209:   }
210:   return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
211:}
