26:/* Build the git child env: a copy of `parent` with the credential-carrying keys
27: * we manage dropped, plus GH_TOKEN/GIT_ASKPASS/GIT_TERMINAL_PROMPT (when a token
28: * is given) and SSH_AUTH_SOCK + GIT_SSH_COMMAND (when a sock is given, so an SSH
29: * remote uses the agent key with a non-interactive TOFU host-key policy).
30: * Returns NULL on OOM. */
31:/* token_fd_target >= 0 selects FD MODE: advertise AIMEE_GIT_TOKEN_FD=<target>
32: * (the askpass reads the token from that inherited fd) and do NOT put the secret
33: * in the env. token_fd_target < 0 is LEGACY ENV MODE: GH_TOKEN=<token>. In both
34: * modes `token` non-empty means "a token exists" (so the askpass is wired). */
35:static char **build_env(char *const *parent, const char *token, const char *shim, const char *sock,
36:                        int token_fd_target)
37:{
38:   size_t pc = 0;
39:   if (parent)
40:      while (parent[pc])
41:         pc++;
42:   /* +token-key,ASKPASS,PROMPT,SSH_AUTH_SOCK,GIT_SSH_COMMAND,NULL */
43:   char **out = calloc(pc + 6, sizeof(char *));
44:   if (!out)
45:      return NULL;
46:   size_t o = 0;
47:   for (size_t i = 0; i < pc; i++)
48:   {
49:      if (is_key(parent[i], "GH_TOKEN") || is_key(parent[i], "GITHUB_TOKEN") ||
50:          is_key(parent[i], "GIT_ASKPASS") || is_key(parent[i], "GIT_TERMINAL_PROMPT") ||
51:          is_key(parent[i], "SSH_AUTH_SOCK") || is_key(parent[i], "GIT_SSH_COMMAND") ||
52:          is_key(parent[i], "AIMEE_GIT_TOKEN_FD"))
53:         continue;
54:      out[o] = strdup(parent[i]);
55:      if (!out[o++])
56:         goto oom;
57:   }
58:   if (token && token[0])
59:   {
60:      char buf[GIT_CRED_TOKEN_MAX + 16];
61:      if (token_fd_target >= 0)
62:         snprintf(buf, sizeof(buf), "AIMEE_GIT_TOKEN_FD=%d", token_fd_target);
63:      else
64:         snprintf(buf, sizeof(buf), "GH_TOKEN=%s", token);
65:      if (!(out[o++] = strdup(buf)))
66:         goto oom;
67:      if (shim && shim[0])
68:      {
69:         char ab[2048];
70:         snprintf(ab, sizeof(ab), "GIT_ASKPASS=%s", shim);
71:         if (!(out[o++] = strdup(ab)))
72:            goto oom;
73:      }
74:      if (!(out[o++] = strdup("GIT_TERMINAL_PROMPT=0")))
75:         goto oom;
76:   }
77:   /* Wire the ssh-agent env only if we can also pin UserKnownHostsFile to this
78:    * principal's own known_hosts (beside the agent socket, in its tmpfs runtime
79:    * dir) — so accept-new's first-use trust is scoped to this principal and never
80:    * bleeds through the OS account's shared ~/.ssh/known_hosts to other tenants.
81:    *
82:    * If we CANNOT derive that per-principal path (a malformed socket with no
83:    * directory component, or an implausibly long path that truncates), we add
84:    * NEITHER SSH_AUTH_SOCK nor GIT_SSH_COMMAND: better to fall back to no-SSH
85:    * (the caller then normalizes to HTTPS) than to run accept-new against the
