200:int git_project_org_candidates(const char *url, char *out, size_t cap)
201:{
202:   if (!url || !out || cap == 0)
203:      return -1;
204:   out[0] = '\0';
205:   char remote[GP_PATH_MAX];
206:   if (git_project_canonical_remote(url, remote, sizeof(remote)) != 0)
207:      return -1;
208:   const char *scheme_end = strstr(remote, "://");
209:   if (!scheme_end)
210:      return -1;
211:   const char *path = strchr(scheme_end + 3, '/');
212:   if (!path)
213:      return -1;
214:   path++;
215:   const char *last_slash = strrchr(path, '/');
216:   if (!last_slash || last_slash == path)
217:      return -1;
218:   /* Sanitize each owner segment independently and join with ", ". */
219:   size_t o = 0;
220:   const char *seg = path;
221:   while (seg < last_slash)
222:   {
223:      const char *end = memchr(seg, '/', (size_t)(last_slash - seg));
224:      if (!end)
225:         end = last_slash;
226:      char raw[WS_REF_COMP_MAX * 2], clean[WS_REF_COMP_MAX + 1];
227:      size_t sl = (size_t)(end - seg);
228:      if (sl > 0 && sl < sizeof(raw))
229:      {
230:         memcpy(raw, seg, sl);
231:         raw[sl] = '\0';
232:         if (sanitize_org(raw, clean, sizeof(clean)) == 0)
233:         {
234:            int n = snprintf(out + o, cap - o, "%s%s", o ? ", " : "", clean);
235:            if (n < 0 || (size_t)n >= cap - o)
236:               break;
237:            o += (size_t)n;
238:         }
239:      }
240:      seg = end + 1;
241:   }
242:   return o > 0 ? 0 : -1;
243:}
