247:int git_cred_forge_configured(void)
248:{
249:   /* Any per-host vault entry means git is configured, whatever repo is in play.
250:    * Host NAMES only — git_host_cred_list never returns tokens, so this asks the
251:    * question without materialising a secret. */
252:   char hosts[1][GIT_HOST_MAX];
253:   if (git_host_cred_list(hosts, 1) > 0)
254:      return 1;
255:
256:   /* Else the server's own identity (a forge App installation / AIMEE_FORGE_TOKEN). */
257:   char token[GIT_CRED_TOKEN_MAX] = {0};
258:   int have = (forge_cred_server_identity(token, sizeof(token), NULL, 0) == 1 && token[0]);
259:   volatile char *p = (volatile char *)token; /* never let the token outlive the check */
260:   for (size_t i = 0; i < sizeof(token); i++)
261:      p[i] = 0;
262:   return have;
263:}
