265:void git_cred_inject_free_env(char **envp)
266:{
267:   if (!envp)
268:      return;
269:   for (int i = 0; envp[i]; i++)
270:   {
271:      /* zero a GH_TOKEN entry's secret before freeing so it doesn't linger */
272:      if (is_key(envp[i], "GH_TOKEN"))
273:      {
274:         volatile char *p = (volatile char *)envp[i];
275:         for (size_t j = 0; p[j]; j++)
276:            p[j] = 0;
277:      }
278:      free(envp[i]);
279:   }
280:   free(envp);
281:}
