62:/* Push a freshly cloned webuser project into aimee-kb (/v1/code/scan) so the
63: * curator queues its code units for synthesis + embedding. index_scan_project
64: * only feeds this server's local lexical index — without this push a
65: * GUI-cloned repo never reaches the kb (no code_embeddings, no corpus).
66: * Best-effort: clone success never depends on the knowledge service; the
67: * outcome is reported on `out` as kb_indexed (+ kb_reason on failure). */
68:static void rh_clone_kb_scan(const char *pname, const char *dest, cJSON *out)
69:{
70:   if (!kb_client_is_live())
71:   {
72:      cJSON_AddBoolToObject(out, "kb_indexed", 0);
73:      cJSON_AddStringToObject(out, "kb_reason", "knowledge service unavailable");
74:      return;
75:   }
76:   kb_client_index_scan_result_t res;
77:   memset(&res, 0, sizeof(res));
78:   int rc = kb_client_index_scan(pname, dest, 0, &res);
79:   int ok = (rc == 0 && !res.skipped);
80:   cJSON_AddBoolToObject(out, "kb_indexed", ok);
81:   if (!ok)
82:   {
83:      cJSON_AddStringToObject(out, "kb_reason",
84:                              res.reason[0] ? res.reason : "knowledge service unavailable");
85:      LOG_WARN("server.workspace", "clone: kb code scan skipped for project '%s': %s", pname,
86:               res.message[0] ? res.message : (res.reason[0] ? res.reason : "unavailable"));
87:   }
