81:            if (dup2(inherit_fd, target_fd) < 0) /* dup2 clears CLOEXEC on target_fd */
82:               _exit(127);
83:         }
84:         else if (fcntl(target_fd, F_SETFD, 0) < 0)
85:         {
86:            _exit(127);
87:         }
88:      }
