198:      if (mfd >= 0 && write(mfd, token, tn) == (ssize_t)tn && write(mfd, "\n", 1) == 1)
199:         token_fd = mfd;
200:      else
201:      {
202:         if (mfd >= 0)
203:            close(mfd);
204:         have_token = 0; /* fail closed */
205:      }
206:   }
