177:char **git_cred_inject_build_env_for_repo(const char *principal, const char *remote_url,
178:                                          const char *repo_dir, const char *preferred_token,
179:                                          char *const *parent_environ, int *out_token_fd)
180:{
181:   if (out_token_fd)
182:      *out_token_fd = -1;
183:   const int fd_mode = (out_token_fd != NULL);
184:
185:   char token[GIT_CRED_TOKEN_MAX] = {0};
186:   int have_token =
187:       resolve_token(principal, remote_url, repo_dir, preferred_token, token, sizeof(token));
188:
189:   /* FD MODE: stage the token in an anonymous CLOEXEC memfd (never a named path,
190:    * never in the env). The askpass reads it via /proc/self/fd/<target>; the
191:    * caller inherits this fd into git and closes it after. memfd failure fails
192:    * closed (drop the token) rather than silently leaking it to the env. */
193:   int token_fd = -1;
194:   if (have_token && fd_mode)
195:   {
196:      int mfd = memfd_create("c", MFD_CLOEXEC); /* opaque name: don't advertise a cred in fdinfo */
197:      size_t tn = strlen(token);
198:      if (mfd >= 0 && write(mfd, token, tn) == (ssize_t)tn && write(mfd, "\n", 1) == 1)
199:         token_fd = mfd;
200:      else
201:      {
202:         if (mfd >= 0)
203:            close(mfd);
204:         have_token = 0; /* fail closed */
205:      }
206:   }
207:
208:   /* Start (or reuse) the user's in-memory ssh-agent if they have a vaulted SSH
209:    * key (WP-C2); the key never touches disk. 1 = sock ready. */
210:   char sock[2048];
211:   int have_sock = (git_ssh_agent_ensure(principal, sock, sizeof(sock)) == 1);
212:
213:   char **envp = NULL;
214:   if (have_token || have_sock)
215:      envp = build_env(parent_environ, have_token ? token : NULL, forge_cred_askpass_shim(),
216:                       have_sock ? sock : NULL,
217:                       (fd_mode && have_token) ? GIT_CRED_TOKEN_TARGET_FD : -1);
218:
219:   if (!envp && token_fd >= 0) /* build failed → don't leak the memfd */
220:   {
221:      close(token_fd);
222:      token_fd = -1;
223:   }
224:
225:   /* Wipe our stack copy of the token unconditionally (the buffer is zero-inited,
226:    * so this is always safe). In fd mode the only remaining plaintext is inside
227:    * the memfd (kernel memory, closed by the caller after exec); in env mode it
228:    * is the GH_TOKEN entry git_cred_inject_free_env zeroes. */
229:   wipe(token, sizeof(token));
230:   if (out_token_fd)
231:      *out_token_fd = token_fd;
232:   return envp;
233:}
