351:   }
352:   /* Reject an empty or flag-like URL. The '--' separator below also stops git
353:    * from treating the URL as an option, but reject the obvious case early. */
354:   if (!url || !url[0] || url[0] == '-')
355:   {
356:      snprintf(err, errlen, "invalid repository URL");
357:      return -1;
358:   }
359:   /* No control chars / whitespace in the URL (defensive; argv already avoids a
360:    * shell, but keep the value clean for logs and git). */
361:   for (const char *p = url; *p; p++)
362:      if ((unsigned char)*p < 0x20 || *p == ' ')
363:      {
364:         snprintf(err, errlen, "invalid repository URL");
365:         return -1;
366:      }
