401:      return -1;
402:   }
403:
404:   /* ---- lifecycle-locked section: conflict checks -> register -> create ----
405:    * The first-component lock serializes flat/org namespace conflicts,
406:    * registration, publication, deletion, and org pruning deployment-wide. */
407:   int lockfd = ws_reg_lock(ref);
408:   if (lockfd < 0)
409:   {
410:      snprintf(err, errlen, "could not acquire the project lifecycle lock");
411:      return -1;
412:   }
413:   int registered = 0, rootfd = -1, orgfd = -1, tmpfd = -1, destfd_parent = -1;
414:   char tmpname[WS_REF_COMP_MAX + 32];
415:   tmpname[0] = '\0';
416:   int rc_final = -1;
417:
418:   rootfd = ws_scope_open_user_root(principal);
419:   if (rootfd < 0)
420:   {
421:      snprintf(err, errlen, "could not open the workspace root");
422:      goto out;
423:   }
424:
425:   /* Caller's own tree: the target must not exist (as anything). */
426:   {
427:      struct stat st;
428:      const char *probe = org[0] ? org : repo;
429:      if (org[0])
430:      {
431:         int ofd = ws_scope_openat2_dir(rootfd, org);
432:         if (ofd >= 0)
433:         {
434:            int exists = fstatat(ofd, repo, &st, AT_SYMLINK_NOFOLLOW) == 0;
