535:      }
536:      struct stat ost;
537:      if (fstat(orgfd, &ost) != 0 || !S_ISDIR(ost.st_mode) || ost.st_uid != geteuid())
538:      {
539:         snprintf(err, errlen, "org directory failed the ownership check");
540:         goto out;
541:      }
542:   }
543:   destfd_parent = org[0] ? orgfd : rootfd;
544:   snprintf(tmpname, sizeof(tmpname), ".tmp-%s-%d", repo, (int)getpid());
545:   /* Stale leftover from a crashed clone only: the cleanup targets this exact
