245:/* Recursively remove `name` (a directory tree) under `parentfd`. Every descent
246: * uses O_NOFOLLOW — directory symlinks are unlinked as entries, never
247: * followed. Best-effort; returns 0 when the entry is gone. `tick` (optional)
248: * is a progress hook invoked per entry: a non-zero return STOPS the walk
249: * immediately (the delete path uses it to heartbeat the purge fence and to
250: * bail when fence ownership is lost — the partial tree is retried by
251: * re-running the idempotent delete). */
252:static int rm_rf_at_tick(int parentfd, const char *name, int (*tick)(void *), void *tick_ctx)
253:{
254:   if (tick && tick(tick_ctx) != 0)
255:      return -1;
256:   int fd = openat(parentfd, name, O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
257:   if (fd < 0)
258:      return unlinkat(parentfd, name, 0) == 0 || errno == ENOENT ? 0 : -1;
259:   DIR *d = fdopendir(fd);
260:   if (!d)
261:   {
262:      close(fd);
263:      return -1;
264:   }
265:   int stopped = 0;
266:   struct dirent *e;
267:   while ((e = readdir(d)) != NULL)
268:   {
269:      if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0)
270:         continue;
271:      if (tick && tick(tick_ctx) != 0)
272:      {
273:         stopped = 1;
274:         break;
275:      }
276:      struct stat st;
277:      if (fstatat(fd, e->d_name, &st, AT_SYMLINK_NOFOLLOW) != 0)
278:         continue;
279:      if (S_ISDIR(st.st_mode))
280:      {
281:         if (rm_rf_at_tick(fd, e->d_name, tick, tick_ctx) != 0 && tick && tick(tick_ctx) != 0)
282:         {
283:            stopped = 1;
284:            break;
285:         }
286:      }
287:      else
288:         unlinkat(fd, e->d_name, 0);
289:   }
290:   closedir(d); /* closes fd */
291:   if (stopped)
292:      return -1;
293:   return unlinkat(parentfd, name, AT_REMOVEDIR) == 0 ? 0 : -1;
294:}
