324:int git_project_clone(const char *principal, const char *url, const char *name, const char *org_in,
325:                      const char *token, char *out_path, size_t path_cap, char *out_ref,
326:                      size_t ref_cap, char *err, size_t errlen)
327:{
328:   if (err && errlen)
329:      err[0] = '\0';
330:   if (out_path && path_cap)
331:      out_path[0] = '\0';
332:   if (out_ref && ref_cap)
333:      out_ref[0] = '\0';
