80:/* The same, for a value the catalog declared as a double. A cost parsed as an
81:   integer is a different number, and one that still looks like a price. */
82:static int parse_double(const char *text, double *out)
83:{
84:   if (!text || !text[0])
85:      return 1;
86:   char *end = NULL;
87:   errno = 0;
88:   double value = strtod(text, &end);
89:   if (errno != 0 || !end || *end != '\0')
90:      return 1;
91:   *out = value;
92:   return 0;
93:}
