95:/* status(u32) | field_count(u32) | (len(u32) | bytes) * count. A write answers
96:   with no values, a read with one, a row with a value per member. */
97:static uint32_t write_reply(uint8_t *out, uint32_t cap, uint32_t *out_len, uint32_t status,
98:                            const char *const *values, uint32_t count)
99:{
100:   uint32_t at = 8u;
101:   for (uint32_t i = 0; i < count; ++i)
102:   {
103:      uint32_t n = (uint32_t)strlen(values[i]);
104:      if (cap < at + 4u + n)
105:         return AIMEE_DB1_STATUS_FAILED;
106:      aimee_db1_put_u32(out + at, n);
107:      at += 4u;
108:      if (n)
109:         memcpy(out + at, values[i], n);
110:      at += n;
111:   }
112:   if (cap < 8u)
113:      return AIMEE_DB1_STATUS_FAILED;
114:   aimee_db1_put_u32(out, status);
115:   aimee_db1_put_u32(out + 4u, count);
116:   *out_len = at;
117:   return status;
118:}
